window.QOL_PACK = {"manifest":"{\n  \"format_version\": 3,\n  \"header\": {\n    \"name\": \"QoL Add-on\",\n    \"description\": \"Vanilla-feeling quality-of-life features.\",\n    \"uuid\": \"da4dcbf0-26b6-4e7c-8401-2258d880e758\",\n    \"version\": \"0.3.0\",\n    \"min_engine_version\": \"1.26.60\"\n  },\n  \"modules\": [\n    {\n      \"type\": \"script\",\n      \"language\": \"javascript\",\n      \"uuid\": \"8ed2e29a-948f-490b-a54c-c366e78a2c5f\",\n      \"version\": \"0.3.0\",\n      \"entry\": \"scripts/main.js\"\n    }\n  ],\n  \"dependencies\": [\n    {\n      \"module_name\": \"@minecraft/server\",\n      \"version\": \"2.11.0\"\n    },\n    {\n      \"module_name\": \"@minecraft/server-ui\",\n      \"version\": \"2.3.0\"\n    }\n  ],\n  \"metadata\": {\n    \"authors\": [\n      \"Rakoren\"\n    ],\n    \"product_type\": \"addon\"\n  },\n  \"settings\": [\n    {\n      \"type\": \"label\",\n      \"text\": \"World-wide switches (world owner only). Each player picks their own settings in game: sneak + jump.\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Hello (dev test)\",\n      \"name\": \"qol:hello\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Veinminer\",\n      \"name\": \"qol:veinminer\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Tree felling\",\n      \"name\": \"qol:tree_felling\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Auto fisher\",\n      \"name\": \"qol:auto_fisher\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Auto-replant\",\n      \"name\": \"qol:auto_replant\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Tool warning\",\n      \"name\": \"qol:tool_warning\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Death coordinates\",\n      \"name\": \"qol:death_coords\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Sorting\",\n      \"name\": \"qol:sorting\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Hotbar swap\",\n      \"name\": \"qol:hotbar_swap\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Gravestone\",\n      \"name\": \"qol:gravestone\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Auto-restock hotbar\",\n      \"name\": \"qol:restock\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"One-player sleep\",\n      \"name\": \"qol:sleep\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Light overlay\",\n      \"name\": \"qol:light_overlay\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Chunk borders\",\n      \"name\": \"qol:chunk_borders\",\n      \"default\": true\n    },\n    {\n      \"type\": \"toggle\",\n      \"text\": \"Auto-torch\",\n      \"name\": \"qol:auto_torch\",\n      \"default\": true\n    },\n    {\n      \"type\": \"label\",\n      \"text\": \"World limits (players can lower these, never raise them)\"\n    },\n    {\n      \"type\": \"slider\",\n      \"text\": \"Veinminer: max blocks\",\n      \"min\": 8,\n      \"max\": 64,\n      \"step\": 8,\n      \"default\": 64,\n      \"name\": \"qol:veinminer_cap\"\n    },\n    {\n      \"type\": \"slider\",\n      \"text\": \"Tree felling: max logs\",\n      \"min\": 16,\n      \"max\": 128,\n      \"step\": 16,\n      \"default\": 128,\n      \"name\": \"qol:tree_felling_cap\"\n    },\n    {\n      \"type\": \"slider\",\n      \"text\": \"Auto-replant: max crops per field\",\n      \"min\": 16,\n      \"max\": 256,\n      \"step\": 16,\n      \"default\": 256,\n      \"name\": \"qol:auto_replant_cap\"\n    },\n    {\n      \"type\": \"slider\",\n      \"text\": \"One-player sleep: % of players who must sleep\",\n      \"min\": 1,\n      \"max\": 100,\n      \"step\": 1,\n      \"default\": 1,\n      \"name\": \"qol:sleep_percent\"\n    }\n  ]\n}\n","modules":[{"id":"hello","name":"Hello (dev test)","default":true,"description":"Core smoke test. Not shipped in releases.","category":"dev","how":"","dev":true,"world":[],"resources":false,"hasCode":true},{"id":"veinminer","name":"Veinminer","default":true,"description":"Sneak-mine ore veins. Costs real durability.","category":"mining","how":"Sneak and mine an ore with a pickaxe: the whole vein breaks. Each extra block costs durability, and it stops with 1 durability left.","dev":false,"world":[{"key":"cap","type":"slider","text":"Veinminer: max blocks","min":8,"max":64,"step":8,"default":64}],"resources":false,"hasCode":true},{"id":"tree-felling","name":"Tree felling","default":true,"description":"Sneak-chop whole trees. Costs real durability.","category":"mining","how":"Sneak and chop a log with an axe: the whole tree comes down and a sapling from your inventory is planted. Same durability rules as veinminer.","dev":false,"world":[{"key":"cap","type":"slider","text":"Tree felling: max logs","min":16,"max":128,"step":16,"default":128}],"resources":false,"hasCode":true},{"id":"auto-fisher","name":"Auto fisher","default":true,"description":"Reels in your catch when a fish bites. You still cast each time.","category":"farming","how":"Cast as normal. When a fish bites, the catch is reeled in for you. You still cast every time, so it is not AFK fishing.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"auto-replant","name":"Auto-replant","default":true,"description":"Harvested crops replant themselves. A hoe harvests and replants the whole field.","category":"farming","how":"Break a grown crop with anything and it replants from its own drops. With a hoe, the whole connected field is harvested and replanted.","dev":false,"world":[{"key":"cap","type":"slider","text":"Auto-replant: max crops per field","min":16,"max":256,"step":16,"default":256}],"resources":false,"hasCode":true},{"id":"tool-warning","name":"Tool warning","default":true,"description":"Warns before a tool breaks.","category":"mining","how":"A sound and a message when the tool in your hand is about to break.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"death-coords","name":"Death coordinates","default":true,"description":"Posts where you died.","category":"survival","how":"Posts your death coordinates in chat.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"sorting","name":"Sorting","default":true,"description":"Sort chests and inventory.","category":"inventory","how":"Sneak + use a chest with an empty hand to sort it by category (or A-Z). Sneak + clock sorts your own inventory.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"hotbar-swap","name":"Hotbar swap","default":true,"description":"Swap hotbar with an inventory row.","category":"inventory","how":"Use a compass to swap your hotbar with an inventory row. The menu can put the compass in your offhand, and double-tap sneak can do the swap.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"gravestone","name":"Gravestone","default":true,"description":"Your drops go into a chest grave on death. Lava and void deaths move to safe ground.","category":"survival","how":"Your drops go into a chest with a sign where you died. Lava and void deaths move it to safe ground. Only you can open it.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"restock","name":"Auto-restock hotbar","default":true,"description":"Refills an emptied hotbar slot from your inventory.","category":"inventory","how":"When the stack in your hand runs out or a tool breaks, a matching one from your inventory takes its place.","dev":false,"world":[],"resources":false,"hasCode":true},{"id":"sleep","name":"One-player sleep","default":true,"description":"One player in bed skips the night.","category":"survival","how":"Only one player needs to sleep to skip the night. The world owner can raise the % on the Behavior Packs screen.","dev":false,"world":[{"key":"percent","type":"slider","text":"One-player sleep: % of players who must sleep","min":1,"max":100,"step":1,"default":1}],"resources":false,"hasCode":true},{"id":"light-overlay","name":"Light overlay","default":true,"description":"Shows where mobs can spawn while you hold a torch.","category":"mining","how":"Hold a torch (or lantern): spots where mobs can spawn get a red marker (any time) or yellow marker (at night). Menu can make it always on. Needs the QoL Overlays resource pack.","dev":false,"world":[],"resources":true,"hasCode":true},{"id":"chunk-borders","name":"Chunk borders","default":true,"description":"Outlines the chunk you're standing in.","category":"survival","how":"Menu (sneak + jump) → Chunk borders on/off. Yellow posts at the chunk corners, cyan lines along its edges. Needs the QoL Overlays resource pack.","dev":false,"world":[],"resources":true,"hasCode":true},{"id":"auto-torch","name":"Auto-torch","default":true,"description":"Places a torch from your last hotbar slot when it gets dark while mining.","category":"mining","how":"Hold a pickaxe with torches in your last hotbar slot. When the spot you're standing on is dark enough for mobs to spawn, a torch is placed there and taken from that slot.","dev":false,"world":[],"resources":false,"hasCode":true}],"files":{"scripts/core/commands.js":"// Slash commands. PC convenience only; console uses the clock.\nimport {\n  system,\n  Player,\n  CommandPermissionLevel,\n  CustomCommandStatus,\n} from \"@minecraft/server\";\nimport { openSettings } from \"./ui.js\";\n\nexport function initCommands() {\n  system.beforeEvents.startup.subscribe((ev) => {\n    ev.customCommandRegistry.registerCommand(\n      {\n        name: \"qol:settings\",\n        description: \"Open QoL add-on settings\",\n        permissionLevel: CommandPermissionLevel.Any,\n        cheatsRequired: false,\n      },\n      (origin) => {\n        const player = origin.sourceEntity;\n        if (!(player instanceof Player)) {\n          return { status: CustomCommandStatus.Failure, message: \"Players only.\" };\n        }\n        // Callback runs in restricted mode; showWithRetry waits out the open chat.\n        system.run(() => openSettings(player));\n        return { status: CustomCommandStatus.Success };\n      },\n    );\n  });\n}\n","scripts/core/feedback.js":"// Standard response to an instant action: click sound + actionbar text. Never a form.\n\nexport function feedback(player, text, { sound = \"random.click\", pitch = 1.2, volume = 0.4 } = {}) {\n  player.onScreenDisplay.setActionBar(text);\n  player.playSound(sound, { pitch, volume });\n}\n","scripts/core/registry.js":"// Validates module definitions, builds each module's ctx, and isolates errors.\nimport { system } from \"@minecraft/server\";\nimport { defineFields, validate, getSetting, setSetting } from \"./settings.js\";\nimport { claimTrigger } from \"./triggers.js\";\nimport { feedback } from \"./feedback.js\";\nimport { worldAllows, worldValue } from \"./world.js\";\n\nconst FIELD_TYPES = [\"toggle\", \"slider\", \"dropdown\"];\n\nfunction makeGuard(moduleId) {\n  return (fn) =>\n    (...args) => {\n      try {\n        return fn(...args);\n      } catch (e) {\n        console.warn(`[qol:${moduleId}] ${e}\\n${e?.stack ?? \"\"}`);\n      }\n    };\n}\n\n/** Returns a list of problems; empty means OK. */\nfunction check(def, meta, seen) {\n  const problems = [];\n  if (!def || typeof def.id !== \"string\") return [\"module has no id\"];\n  if (!meta[def.id]) problems.push(`\"${def.id}\" is not in modules.json`);\n  if (seen.has(def.id)) problems.push(`duplicate module id \"${def.id}\"`);\n  if (typeof def.register !== \"function\") problems.push(\"missing register(ctx)\");\n\n  const keys = new Set();\n  for (const f of def.settings ?? []) {\n    if (!f.key || f.key === \"enabled\") problems.push(`bad setting key \"${f.key}\"`);\n    else if (keys.has(f.key)) problems.push(`duplicate setting \"${f.key}\"`);\n    keys.add(f.key);\n    if (!FIELD_TYPES.includes(f.type)) {\n      problems.push(`setting \"${f.key}\" has unknown type \"${f.type}\"`);\n      continue;\n    }\n    if (f.type === \"slider\" && !(f.min < f.max)) problems.push(`slider \"${f.key}\" needs min < max`);\n    if (f.type === \"dropdown\" && !(f.options?.length > 0)) problems.push(`dropdown \"${f.key}\" has no options`);\n    else if (validate(f, f.default) !== f.default) problems.push(`setting \"${f.key}\" default is out of range`);\n  }\n  for (const m of def.menu ?? []) {\n    if (!m.id || !m.label || typeof m.run !== \"function\") problems.push(`bad menu entry \"${m.id}\"`);\n  }\n  return problems;\n}\n\n/**\n * @param {any[]} modules  module definitions in modules.json order\n * @param {Record<string, { name: string, default: boolean }>} meta\n * @returns {Array<{ def: any, ctx: any }>}\n */\nexport function loadModules(modules, meta) {\n  const seen = new Set();\n  const loaded = [];\n\n  for (const def of modules) {\n    const problems = check(def, meta, seen);\n    if (problems.length) {\n      console.warn(`[qol] skipping module ${def?.id ?? \"?\"}: ${problems.join(\"; \")}`);\n      continue;\n    }\n    seen.add(def.id);\n\n    const id = def.id;\n    defineFields(id, [\n      { key: \"enabled\", type: \"toggle\", label: \"Enabled\", default: meta[id].default },\n      ...(def.settings ?? []),\n    ]);\n\n    const guard = makeGuard(id);\n    // World owner's switch (pack settings) beats the player's own toggle.\n    const isEnabled = (player) => worldAllows(id) && getSetting(player, id, \"enabled\");\n    const ctx = {\n      id,\n      get: (player, key) => getSetting(player, id, key),\n      world: (key) => worldValue(id, key),\n      worldAllows: () => worldAllows(id),\n      /** Player setting, capped by the world limit of the same key if there is one. */\n      capped: (player, key) => {\n        const mine = getSetting(player, id, key);\n        const limit = worldValue(id, key);\n        return typeof limit === \"number\" ? Math.min(mine, limit) : mine;\n      },\n      set: (player, key, value) => setSetting(player, id, key, value),\n      isEnabled,\n      // `when(player, block?)` narrows when the handler counts as active; for\n      // block triggers that also decides whether core cancels the container open.\n      on: (trigger, fn, when) => {\n        const gate = when ? guard((p, b) => isEnabled(p) && !!when(p, b)) : isEnabled;\n        try {\n          claimTrigger(trigger, id, guard(fn), gate);\n        } catch (e) {\n          console.warn(`[qol:${id}] ${e}`);\n        }\n      },\n      run: (fn) => system.run(guard(fn)),\n      feedback,\n      guard,\n      log: (...args) => console.warn(`[qol:${id}]`, ...args),\n    };\n\n    try {\n      def.register(ctx);\n      loaded.push({ def, ctx });\n    } catch (e) {\n      console.warn(`[qol:${id}] register() failed, module disabled: ${e}\\n${e?.stack ?? \"\"}`);\n    }\n  }\n  return loaded;\n}\n","scripts/core/settings.js":"// Per-player settings over dynamic properties, with an in-memory cache.\n// Keys: qol:<moduleId>:<key>. Values validated against the field on every read.\nimport { world } from \"@minecraft/server\";\n\nconst PREFIX = \"qol\";\nexport const SCHEMA_KEY = `${PREFIX}:core:schema`;\nexport const SCHEMA_VERSION = 1;\n\n/** @type {Map<string, Map<string, any>>} moduleId -> key -> field */\nconst fieldsByModule = new Map();\n/** @type {Map<string, Map<string, any>>} playerId -> propId -> value */\nconst cache = new Map();\n\nexport function defineFields(moduleId, fields) {\n  fieldsByModule.set(moduleId, new Map(fields.map((f) => [f.key, f])));\n}\n\nexport function getFields(moduleId) {\n  return [...(fieldsByModule.get(moduleId)?.values() ?? [])];\n}\n\n/** Coerce a raw value to something valid for the field, else the field default. */\nexport function validate(field, value) {\n  switch (field.type) {\n    case \"toggle\":\n      return typeof value === \"boolean\" ? value : field.default;\n    case \"slider\": {\n      if (typeof value !== \"number\" || !Number.isFinite(value)) return field.default;\n      const step = field.step ?? 1;\n      let v = Math.min(field.max, Math.max(field.min, value));\n      v = field.min + Math.round((v - field.min) / step) * step;\n      return Math.min(field.max, v);\n    }\n    case \"dropdown\":\n      return field.options.some((o) => o.value === value) ? value : field.default;\n    default:\n      return field.default;\n  }\n}\n\nfunction propId(moduleId, key) {\n  return `${PREFIX}:${moduleId}:${key}`;\n}\n\nfunction playerCache(player) {\n  let c = cache.get(player.id);\n  if (!c) cache.set(player.id, (c = new Map()));\n  return c;\n}\n\nfunction getField(moduleId, key) {\n  const field = fieldsByModule.get(moduleId)?.get(key);\n  if (!field) throw new Error(`Unknown setting ${moduleId}:${key}`);\n  return field;\n}\n\nexport function getSetting(player, moduleId, key) {\n  const field = getField(moduleId, key);\n  const id = propId(moduleId, key);\n  const c = playerCache(player);\n  if (c.has(id)) return c.get(id);\n  const value = validate(field, player.getDynamicProperty(id));\n  c.set(id, value);\n  return value;\n}\n\n/** Must be called outside restricted (before-event) mode. */\nexport function setSetting(player, moduleId, key, value) {\n  const field = getField(moduleId, key);\n  const v = validate(field, value);\n  player.setDynamicProperty(propId(moduleId, key), v);\n  playerCache(player).set(propId(moduleId, key), v);\n  return v;\n}\n\nexport function initSettings() {\n  world.afterEvents.playerLeave.subscribe((ev) => cache.delete(ev.playerId));\n  world.afterEvents.playerSpawn.subscribe((ev) => {\n    if (!ev.initialSpawn) return;\n    if (ev.player.getDynamicProperty(SCHEMA_KEY) === undefined) {\n      ev.player.setDynamicProperty(SCHEMA_KEY, SCHEMA_VERSION);\n    }\n  });\n}\n","scripts/core/start.js":"import { world } from \"@minecraft/server\";\nimport { initSettings } from \"./settings.js\";\nimport { initTriggers, setMenuOpener } from \"./triggers.js\";\nimport { initCommands } from \"./commands.js\";\nimport { loadModules } from \"./registry.js\";\nimport { openMenu, setLoadedModules } from \"./ui.js\";\n\nexport function start(modules, meta) {\n  initSettings();\n  initTriggers();\n  initCommands();\n  setMenuOpener((player) => openMenu(player));\n  initJoinTip();\n  const loaded = loadModules(modules, meta);\n  setLoadedModules(loaded);\n  console.warn(`[qol] loaded ${loaded.length}/${modules.length} modules: ${loaded.map((m) => m.def.id).join(\", \")}`);\n}\n\nconst TIP_KEY = \"qol:core:tipShown\";\n\n/** Tells each player once how to reach the menu without any items. */\nfunction initJoinTip() {\n  world.afterEvents.playerSpawn.subscribe((ev) => {\n    if (!ev.initialSpawn) return;\n    const player = ev.player;\n    try {\n      if (player.getDynamicProperty(TIP_KEY)) return;\n      player.sendMessage(\"§e[QoL]§r Sneak + jump opens the QoL menu and settings (or use a clock).\");\n      player.setDynamicProperty(TIP_KEY, true);\n    } catch (e) {\n      console.warn(`[qol] join tip: ${e}`);\n    }\n  });\n}\n","scripts/core/triggers.js":"// Core owns the trigger-item events so modules never fight over the clock.\n// See docs/CONTRACT.md \"Core triggers\".\nimport { world, system, InputButton, ButtonState } from \"@minecraft/server\";\n\nexport const TRIGGER_ITEMS = {\n  clock: \"minecraft:clock\",\n  compass: \"minecraft:compass\",\n};\n\nexport const TRIGGERS = [\n  \"clock:air:sneak\",\n  \"clock:container:sneak\",\n  \"clock:container\",\n  \"hand:container:sneak\",\n  \"sneak:double\",\n  \"compass:air\",\n];\n\n// Triggers several modules may claim at once. Each claimant gates itself on its\n// own setting (e.g. sorting and hotbar-swap both offer double-tap sneak).\nconst SHARED_TRIGGERS = new Set([\"sneak:double\"]);\n\nconst DOUBLE_SNEAK_WINDOW = 8; // ticks between presses\nconst DOUBLE_SNEAK_COOLDOWN = 40; // ticks (2s)\nconst MENU_GESTURE_COOLDOWN = 20; // ticks between sneak + jump menu opens\n\n/** @type {Map<string, Array<{ moduleId: string, fn: Function, isEnabled: (p: any, block?: any) => boolean }>>} */\nconst handlers = new Map();\n/** @type {((player: any) => void) | undefined} */\nlet menuOpener;\n\nexport function claimTrigger(trigger, moduleId, fn, isEnabled) {\n  if (!TRIGGERS.includes(trigger)) throw new Error(`Unknown trigger \"${trigger}\"`);\n  const list = handlers.get(trigger) ?? [];\n  if (list.length && !SHARED_TRIGGERS.has(trigger)) {\n    throw new Error(`Trigger \"${trigger}\" already claimed by ${list[0].moduleId}`);\n  }\n  list.push({ moduleId, fn, isEnabled });\n  handlers.set(trigger, list);\n}\n\nexport function setMenuOpener(fn) {\n  menuOpener = fn;\n}\n\n/** First enabled claimant of an exclusive trigger. */\nfunction active(trigger, player, block) {\n  return handlers.get(trigger)?.find((h) => h.isEnabled(player, block));\n}\n\n/** Every enabled claimant of a shared trigger. */\nfunction allActive(trigger, player) {\n  return (handlers.get(trigger) ?? []).filter((h) => h.isEnabled(player));\n}\n\nexport function initTriggers() {\n  // Tick of the last block interaction per player, so a block click never\n  // also counts as an in-air use.\n  const lastBlockUse = new Map();\n  const lastSneak = new Map();\n  const sneakCooldown = new Map();\n  const menuCooldown = new Map();\n\n  world.beforeEvents.playerInteractWithBlock.subscribe((ev) => {\n    // Fires repeatedly while the button is held: only run the action on the first.\n    const player = ev.player;\n    lastBlockUse.set(player.id, system.currentTick);\n    const emptyHand = !ev.itemStack;\n    if (!emptyHand && ev.itemStack.typeId !== TRIGGER_ITEMS.clock) return;\n    // Empty hand only counts while sneaking; a plain empty-hand click just opens the chest.\n    if (emptyHand && !player.isSneaking) return;\n\n    let hasInventory = false;\n    try {\n      hasInventory = !!ev.block.getComponent(\"minecraft:inventory\");\n    } catch {\n      hasInventory = false;\n    }\n    if (!hasInventory) return;\n\n    const sneaking = player.isSneaking;\n    const trigger = emptyHand\n      ? \"hand:container:sneak\"\n      : sneaking\n        ? \"clock:container:sneak\"\n        : \"clock:container\";\n    const h = active(trigger, player, ev.block);\n    if (!h) return; // nothing claimed / disabled: chest opens normally\n    // Plain clock acts and the chest still opens; sneak + clock / sneak + empty hand\n    // act and never open it.\n    if (sneaking) ev.cancel = true;\n    if (!ev.isFirstEvent) return;\n    const block = ev.block;\n    system.run(() => h.fn(player, block));\n  });\n\n  world.afterEvents.itemUse.subscribe((ev) => {\n    const player = ev.source;\n    if (lastBlockUse.get(player.id) === system.currentTick) return;\n    const id = ev.itemStack?.typeId;\n    if (id === TRIGGER_ITEMS.clock) {\n      if (player.isSneaking) active(\"clock:air:sneak\", player)?.fn(player);\n      else menuOpener?.(player);\n    } else if (id === TRIGGER_ITEMS.compass) {\n      active(\"compass:air\", player)?.fn(player);\n    }\n  });\n\n  world.afterEvents.playerButtonInput.subscribe(\n    (ev) => {\n      const player = ev.player;\n      const hs = allActive(\"sneak:double\", player);\n      if (!hs.length) return;\n      const now = system.currentTick;\n      if ((sneakCooldown.get(player.id) ?? -Infinity) > now) return;\n      const prev = lastSneak.get(player.id);\n      if (prev !== undefined && now - prev <= DOUBLE_SNEAK_WINDOW) {\n        lastSneak.delete(player.id);\n        sneakCooldown.set(player.id, now + DOUBLE_SNEAK_COOLDOWN);\n        for (const h of hs) h.fn(player);\n      } else {\n        lastSneak.set(player.id, now);\n      }\n    },\n    { buttons: [InputButton.Sneak], state: ButtonState.Pressed },\n  );\n\n  // Sneak + jump opens the QoL menu: the no-item way in, so settings are\n  // reachable before you have a clock. On the ground only, so it doesn't fire\n  // mid-parkour or while swimming.\n  world.afterEvents.playerButtonInput.subscribe(\n    (ev) => {\n      const player = ev.player;\n      if (!player.isSneaking || !player.isOnGround) return;\n      const now = system.currentTick;\n      if ((menuCooldown.get(player.id) ?? -Infinity) > now) return;\n      menuCooldown.set(player.id, now + MENU_GESTURE_COOLDOWN);\n      menuOpener?.(player);\n    },\n    { buttons: [InputButton.Jump], state: ButtonState.Pressed },\n  );\n\n  world.afterEvents.playerLeave.subscribe((ev) => {\n    lastBlockUse.delete(ev.playerId);\n    lastSneak.delete(ev.playerId);\n    sneakCooldown.delete(ev.playerId);\n    menuCooldown.delete(ev.playerId);\n  });\n}\n","scripts/core/ui.js":"// Clock menu + settings forms. Forms are only for the menu and settings,\n// never for instant actions.\nimport { system } from \"@minecraft/server\";\nimport { ActionFormData, ModalFormData, FormCancelationReason } from \"@minecraft/server-ui\";\nimport { getFields, getSetting, setSetting } from \"./settings.js\";\nimport { worldAllows } from \"./world.js\";\n\nconst sleep = (ticks) => new Promise((resolve) => system.runTimeout(() => resolve(undefined), ticks));\n\n/**\n * Show a form, retrying while the player is busy (chat open, other screen).\n * Resolves undefined if it never got through or the player left.\n */\nexport async function showWithRetry(form, player, { tries = 10, interval = 10 } = {}) {\n  for (let i = 0; i < tries; i++) {\n    if (!player.isValid) return undefined;\n    const res = await form.show(player);\n    if (!(res.canceled && res.cancelationReason === FormCancelationReason.UserBusy)) return res;\n    await sleep(interval);\n  }\n  return undefined;\n}\n\n/** @type {Array<{ def: any, ctx: any }>} */\nlet loaded = [];\n\nexport function setLoadedModules(list) {\n  loaded = list;\n}\n\nexport async function openMenu(player) {\n  const entries = [];\n  for (const { def, ctx } of loaded) {\n    if (!ctx.isEnabled(player)) continue;\n    for (const entry of def.menu ?? []) entries.push({ entry, ctx });\n  }\n\n  const form = new ActionFormData().title(\"QoL\");\n  for (const { entry } of entries) form.button(entry.label);\n  form.button(\"Settings\");\n\n  const res = await showWithRetry(form, player);\n  if (!res || res.canceled || res.selection === undefined) return;\n  if (res.selection === entries.length) return openSettings(player);\n  const { entry, ctx } = entries[res.selection];\n  ctx.guard(() => entry.run(player, ctx))();\n}\n\nexport async function openSettings(player) {\n  while (player.isValid) {\n    // Modules the world owner switched off (pack settings) are hidden.\n    // World-only modules (e.g. sleep) have nothing to set per player.\n    const shown = loaded.filter(({ def }) => worldAllows(def.id) && !def.worldOnly);\n    const form = new ActionFormData().title(\"QoL Settings\");\n    for (const { def, ctx } of shown) {\n      form.button(`${def.name}  ${ctx.isEnabled(player) ? \"§aON\" : \"§7OFF\"}`);\n    }\n    const res = await showWithRetry(form, player);\n    if (!res || res.canceled || res.selection === undefined) return;\n    await openModuleSettings(player, shown[res.selection]);\n  }\n}\n\nasync function openModuleSettings(player, { def }) {\n  const fields = getFields(def.id);\n  const form = new ModalFormData().title(def.name).submitButton(\"Save\");\n  for (const f of fields) {\n    const current = getSetting(player, def.id, f.key);\n    if (f.type === \"toggle\") {\n      form.toggle(f.label, { defaultValue: current, tooltip: f.tooltip });\n    } else if (f.type === \"slider\") {\n      form.slider(f.label, f.min, f.max, { valueStep: f.step ?? 1, defaultValue: current, tooltip: f.tooltip });\n    } else if (f.type === \"dropdown\") {\n      const idx = Math.max(0, f.options.findIndex((o) => o.value === current));\n      form.dropdown(f.label, f.options.map((o) => o.label), { defaultValueIndex: idx, tooltip: f.tooltip });\n    }\n  }\n\n  const res = await showWithRetry(form, player);\n  if (!res || res.canceled || !res.formValues) return; // back to the list\n  fields.forEach((f, i) => {\n    let value = res.formValues[i];\n    if (f.type === \"dropdown\") value = f.options[/** @type {number} */ (value)]?.value;\n    setSetting(player, def.id, f.key, value);\n  });\n}\n","scripts/core/world.js":"// World-wide pack settings: the gear on the Behavior Packs screen, set by the\n// world owner. Names come from site/builder.js generatePackSettings():\n// `qol:<id>` (module allowed in this world) and `qol:<id>_<key>` (world limit),\n// with hyphens in ids turned into underscores.\nimport { world, system } from \"@minecraft/server\";\n\n/** @type {{ tick: number, values: Record<string, any> }} */\nlet cache = { tick: -1, values: {} };\n\nfunction values() {\n  // Re-read at most once per tick; values can change when the owner edits them.\n  if (cache.tick !== system.currentTick) {\n    let v = {};\n    try {\n      v = world.getPackSettings() ?? {};\n    } catch {\n      v = {}; // no settings support: everything allowed, no limits\n    }\n    cache = { tick: system.currentTick, values: v };\n  }\n  return cache.values;\n}\n\nconst nameOf = (id, key) => `qol:${id.replace(/-/g, \"_\")}${key ? `_${key}` : \"\"}`;\n\n/** False only when the world owner switched this module off. */\nexport function worldAllows(moduleId) {\n  return values()[nameOf(moduleId)] !== false;\n}\n\n/** A world limit for this module, or undefined if the pack doesn't define one. */\nexport function worldValue(moduleId, key) {\n  return values()[nameOf(moduleId, key)];\n}\n","scripts/lib/bulk-break.js":"// Shared by veinminer + tree-felling: flood fill through connected same-key\n// blocks, vanilla-accurate drops/XP via the loot table, and real durability\n// cost. See docs/MODULES.md and docs/CONTRACT.md \"lib/\".\nimport { world, GameMode } from \"@minecraft/server\";\nimport { getUnbreakingLevel, remainingDurability, damageItem } from \"./items.js\";\n\nconst NEIGHBORS = [];\nfor (let x = -1; x <= 1; x++)\n  for (let y = -1; y <= 1; y++)\n    for (let z = -1; z <= 1; z++) if (x || y || z) NEIGHBORS.push({ x, y, z });\n\nfunction posKey(loc) {\n  return `${loc.x},${loc.y},${loc.z}`;\n}\n\n/**\n * Flood-fills out from `origin` (already broken by the player's own hit)\n * through same-key neighbors, breaking up to `cap - 1` more blocks.\n *\n * @param {object} opts\n * @param {import(\"@minecraft/server\").Player} opts.player\n * @param {import(\"@minecraft/server\").Block} opts.origin  the now-air block the player just broke\n * @param {string} opts.originKey  `key()` applied to the block's type *before* it was broken\n * @param {(typeId: string) => string} opts.key  groups block types that count as the same vein/tree\n * @param {number} opts.cap  vein size cap, including the origin block\n * @param {boolean} opts.protectTool  stop at 1 durability left instead of letting the tool break\n * @param {(block: import(\"@minecraft/server\").Block) => number} [opts.xp]  XP for one extra block (0/omit for none)\n * @returns {{ broken: number, toolBroke: boolean }}\n */\nexport function bulkBreak({ player, origin, originKey, key, cap, protectTool, xp }) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  let tool = container?.getItem(player.selectedSlotIndex);\n  if (!container || !tool) return { broken: 0, toolBroke: false };\n\n  const creative = player.getGameMode() === GameMode.Creative;\n  const unbreaking = getUnbreakingLevel(tool);\n  const dimension = origin.dimension;\n  const lootManager = world.getLootTableManager();\n\n  const seen = new Set([posKey(origin.location)]);\n  const queue = [origin.location];\n  let broken = 0;\n  let toolBroke = false;\n\n  outer: while (queue.length > 0 && broken < cap - 1) {\n    const loc = queue.shift();\n    for (const d of NEIGHBORS) {\n      const next = { x: loc.x + d.x, y: loc.y + d.y, z: loc.z + d.z };\n      const k = posKey(next);\n      if (seen.has(k)) continue;\n      seen.add(k);\n\n      const block = dimension.getBlock(next);\n      if (!block || key(block.permutation.type.id) !== originKey) continue;\n\n      if (!creative && protectTool && remainingDurability(tool) <= 1) break outer;\n\n      const loot = lootManager.generateLootFromBlockPermutation(block.permutation, tool);\n      if (loot === undefined) continue; // tool tier can't harvest this one: skip it\n\n      block.setType(\"minecraft:air\");\n      for (const stack of loot) dimension.spawnItem(stack, block.location);\n      if (!creative) {\n        const amount = xp?.(block) ?? 0;\n        if (amount > 0) dimension.spawnXp(block.location, amount);\n      }\n      broken++;\n\n      if (!creative) {\n        tool = damageItem(tool, unbreaking);\n        if (!tool) {\n          toolBroke = true;\n          break outer;\n        }\n      }\n\n      queue.push(next);\n      if (broken >= cap - 1) break outer;\n    }\n  }\n\n  if (!creative) {\n    container.setItem(player.selectedSlotIndex, tool); // tool undefined when broken: clears the slot\n    if (toolBroke) player.playSound(\"random.break\");\n  }\n\n  return { broken, toolBroke };\n}\n","scripts/lib/containers.js":"// Container helpers for sorting: storage detection and merge + sort\n// (category or alphabetical, see sort-keys.js).\nimport { compareByCategory, compareById } from \"./sort-keys.js\";\n\nconst STORAGE = /(^|_)(chest|barrel|shulker_box)$/;\n\n/** True for player-style storage blocks (chests, barrels, shulker boxes), not furnaces/hoppers/etc. */\nexport function isStorageBlock(block) {\n  return STORAGE.test(block.typeId.replace(\"minecraft:\", \"\"));\n}\n\nexport function getBlockContainer(block) {\n  return block.getComponent(\"minecraft:inventory\")?.container;\n}\n\nexport function getPlayerContainer(player) {\n  return player.getComponent(\"minecraft:inventory\")?.container;\n}\n\n/** Slot range `[from, to)` of a player's inventory: hotbar is 0-8, main inventory 9-35. */\nexport function playerRange(includeHotbar) {\n  return [includeHotbar ? 0 : 9, 36];\n}\n\n/**\n * Merges partial stacks in slots `[from, to)` of `container`, then orders them\n * by `mode` (\"category\" or \"alpha\"), packing empty slots to the end.\n */\nexport function sortRange(container, from = 0, to = container.size, mode = \"category\") {\n  const merged = [];\n  for (let i = from; i < to; i++) {\n    const item = container.getItem(i);\n    if (!item) continue;\n    let left = item.amount;\n    for (const stack of merged) {\n      if (left === 0) break;\n      if (stack.amount >= stack.maxAmount || !stack.isStackableWith(item)) continue;\n      const moved = Math.min(stack.maxAmount - stack.amount, left);\n      stack.amount += moved;\n      left -= moved;\n    }\n    if (left > 0) {\n      const rest = item.clone();\n      rest.amount = left;\n      merged.push(rest);\n    }\n  }\n\n  merged.sort(mode === \"alpha\" ? compareById : compareByCategory);\n\n  for (let i = from; i < to; i++) container.setItem(i, merged[i - from]);\n}\n","scripts/lib/fresh-plants.js":"// Guards something we just planted (a replanted sapling or crop) for a moment,\n// so the player's next swing, still aimed at the spot, doesn't pop it right\n// back off. Breaking it is simply cancelled until the guard runs out.\nimport { world, system } from \"@minecraft/server\";\n\nconst GUARD_TICKS = 40; // 2s\n\n/** @type {Map<string, { until: number, typeId: string }>} */\nconst fresh = new Map();\nconst keyOf = (dimId, l) => `${dimId}|${l.x},${l.y},${l.z}`;\n\nworld.beforeEvents.playerBreakBlock.subscribe((ev) => {\n  if (!fresh.size) return;\n  const key = keyOf(ev.block.dimension.id, ev.block.location);\n  const entry = fresh.get(key);\n  if (!entry) return;\n  if (entry.until < system.currentTick || ev.block.typeId !== entry.typeId) {\n    fresh.delete(key);\n    return;\n  }\n  ev.cancel = true;\n});\n\n/** Protect the block now at `block`'s spot from being broken for a short while. */\nexport function protectFresh(block, ticks = GUARD_TICKS) {\n  const now = system.currentTick;\n  if (fresh.size > 512) {\n    for (const [k, e] of fresh) if (e.until < now) fresh.delete(k);\n  }\n  fresh.set(keyOf(block.dimension.id, block.location), { until: now + ticks, typeId: block.typeId });\n}\n\n/** Removes one `itemId` from the player's inventory. Returns true if there was one. */\nexport function takeFromInventory(player, itemId) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  if (!container) return false;\n  for (let i = 0; i < container.size; i++) {\n    const stack = container.getItem(i);\n    if (stack?.typeId !== itemId) continue;\n    if (stack.amount > 1) {\n      stack.amount -= 1;\n      container.setItem(i, stack);\n    } else {\n      container.setItem(i, undefined);\n    }\n    return true;\n  }\n  return false;\n}\n","scripts/lib/items.js":"// Held-item helpers: read the item in a player's selected slot and spend\n// durability the vanilla way, via getDamageChance (no hand-rolled Unbreaking\n// odds). See docs/VERIFY.md \"Durability + Unbreaking\".\n\nexport function getUnbreakingLevel(item) {\n  return item.getComponent(\"minecraft:enchantable\")?.getEnchantment(\"unbreaking\")?.level ?? 0;\n}\n\n/** Durability points left before the tool breaks, or Infinity if unbreakable/no durability component. */\nexport function remainingDurability(item) {\n  const durability = item.getComponent(\"minecraft:durability\");\n  if (!durability || durability.unbreakable) return Infinity;\n  return durability.maxDurability - durability.damage;\n}\n\n/**\n * Spends one vanilla \"use\" of durability on `item`, following the odds from\n * getDamageChance(unbreakingLevel). Mutates and returns the item, or\n * returns undefined if this use broke it.\n */\nexport function damageItem(item, unbreakingLevel) {\n  const durability = item.getComponent(\"minecraft:durability\");\n  if (!durability || durability.unbreakable) return item;\n  // getDamageChance is a percentage: 100 with no Unbreaking, 25 at Unbreaking III.\n  if (Math.random() * 100 >= durability.getDamageChance(unbreakingLevel)) return item;\n  durability.damage += 1;\n  return durability.damage >= durability.maxDurability ? undefined : item;\n}\n","scripts/lib/light.js":"// Light + mob-spawn helpers shared by light-overlay and auto-torch.\n//\n// Bedrock hostile mobs spawn on a solid floor where the *block* light is 0\n// (sky light decides day vs. always). The API gives total light\n// (getLightLevel) and sky light (getSkyLightLevel), not block light, so:\n//   total > sky  -> something is lighting it: block light >= 1, no spawns\n//   total <= sky -> block light could be 0: assume it is (errs toward warning)\n// Under cover (sky <= 7) that's exact. Out in the open it can over-warn; see\n// docs/VERIFY.md \"Light levels\". Use `scriptevent qol:light` to calibrate.\n\n// Floors mobs can't spawn on (substring match on the block id).\nconst NO_SPAWN_FLOOR = [\n  \"glass\", \"leaves\", \"slab\", \"stairs\", \"fence\", \"wall\", \"carpet\", \"torch\", \"pane\", \"door\", \"button\",\n  \"pressure_plate\", \"rail\", \"sign\", \"bed\", \"chest\", \"barrel\", \"ice\", \"farmland\", \"path\", \"snow_layer\",\n  \"flower\", \"sapling\", \"bars\", \"lantern\", \"campfire\", \"chain\", \"ladder\", \"vine\", \"scaffolding\", \"cactus\",\n  \"magma\", \"honey\", \"slime\", \"azalea\", \"lily\", \"spawner\", \"piston\", \"hopper\", \"anvil\", \"cauldron\",\n  \"brewing\", \"enchanting\", \"lectern\", \"table\", \"furnace\", \"smoker\", \"bell\", \"banner\", \"skull\", \"head\",\n  \"candle\", \"pot\", \"lever\", \"repeater\", \"comparator\", \"redstone_wire\", \"glow_lichen\", \"moss_carpet\",\n  \"grass\", \"fern\", \"bush\", \"kelp\", \"seagrass\", \"coral\", \"mushroom\", \"roots\", \"sprouts\", \"fungus\", \"web\",\n];\n\nfunction safeBlock(dimension, loc) {\n  try {\n    return dimension.getBlock(loc);\n  } catch {\n    return undefined;\n  }\n}\n\nfunction isSpawnFloor(block) {\n  if (!block || block.isAir || block.isLiquid) return false;\n  const id = block.typeId;\n  if (id.includes(\"slab\")) return id.includes(\"double\");\n  if (id === \"minecraft:grass_block\" || id === \"minecraft:dirt_with_roots\") return true;\n  return !NO_SPAWN_FLOOR.some((k) => id.includes(k));\n}\n\n/** A mob could stand at `loc`: air here and above, a spawnable floor below. */\nexport function canStandAt(dimension, loc) {\n  const here = safeBlock(dimension, loc);\n  if (!here?.isAir) return false;\n  if (!safeBlock(dimension, { x: loc.x, y: loc.y + 1, z: loc.z })?.isAir) return false;\n  return isSpawnFloor(safeBlock(dimension, { x: loc.x, y: loc.y - 1, z: loc.z }));\n}\n\n/** { total, sky, blockLit } for the block space at `loc`, or undefined if unloaded. */\nexport function lightAt(dimension, loc) {\n  try {\n    const total = dimension.getLightLevel(loc);\n    const sky = dimension.getSkyLightLevel(loc);\n    return { total, sky, blockLit: total > sky };\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * \"always\" (hostiles can spawn any time), \"night\" (only at night / in the\n * open), or undefined (lit, or nothing can stand there).\n */\nexport function spawnState(dimension, loc) {\n  if (!canStandAt(dimension, loc)) return undefined;\n  const l = lightAt(dimension, loc);\n  if (!l || l.blockLit) return undefined;\n  return l.sky <= 7 ? \"always\" : \"night\";\n}\n","scripts/lib/sort-keys.js":"// Category + color sort order. Hand-built lists, no assets: an item's category\n// comes from its id pattern, its food component, or whether it places a block.\n// Within a category, colored variants (wool, concrete, glass, beds...) sit\n// together in the creative-inventory color order. See docs/MODULES.md#sorting.\nimport { BlockTypes } from \"@minecraft/server\";\n\n// Creative inventory color order. Two-word colors first so \"light_gray\" isn't read as \"gray\".\nconst COLORS = [\n  \"white\",\n  \"light_gray\",\n  \"gray\",\n  \"black\",\n  \"brown\",\n  \"red\",\n  \"orange\",\n  \"yellow\",\n  \"lime\",\n  \"green\",\n  \"cyan\",\n  \"light_blue\",\n  \"blue\",\n  \"purple\",\n  \"magenta\",\n  \"pink\",\n];\nconst COLOR_MATCH = [...COLORS].sort((a, b) => b.length - a.length);\n\nconst TOOLS = /(_sword|_axe|_pickaxe|_shovel|_hoe|_spear)$|^(bow|crossbow|trident|mace|shears|flint_and_steel|fishing_rod|carrot_on_a_stick|warped_fungus_on_a_stick|brush|shield|spyglass|compass|recovery_compass|clock|lead|name_tag|saddle)$/;\nconst ARMOR = /(_helmet|_chestplate|_leggings|_boots|_horse_armor)$|^(elytra|wolf_armor|turtle_helmet)$/;\nconst MATERIALS = /(_ingot|_nugget)$|^raw_|^(coal|charcoal|diamond|emerald|lapis_lazuli|redstone|quartz|netherite_scrap|amethyst_shard|copper_ingot|flint|stick|glowstone_dust|resin_brick|brick|nether_brick|prismarine_shard|prismarine_crystals|echo_shard|disc_fragment_5|heavy_core|breeze_rod)$/;\nconst MOB_DROPS = /^(string|bone|bone_meal|gunpowder|spider_eye|fermented_spider_eye|ender_pearl|ender_eye|slime_ball|magma_cream|leather|rabbit_hide|rabbit_foot|feather|blaze_rod|blaze_powder|ghast_tear|phantom_membrane|ink_sac|glow_ink_sac|nautilus_shell|scute|turtle_scute|armadillo_scute|shulker_shell|honeycomb|egg|blue_egg|brown_egg|nether_star|dragon_breath)$/;\nconst AMMO_POTIONS = /(arrow|potion)$|^(firework_rocket|firework_star|wind_charge|fire_charge|snowball|experience_bottle|totem_of_undying)$/;\n\n// Category order in the sorted container.\nconst CAT = { tools: 0, armor: 1, ammo: 2, food: 3, materials: 4, drops: 5, blocks: 6, misc: 7 };\n\n/** @type {Map<string, number>} */\nconst catCache = new Map();\n\n/** @param {import(\"@minecraft/server\").ItemStack} item */\nfunction category(item) {\n  const id = item.typeId;\n  const cached = catCache.get(id);\n  if (cached !== undefined) return cached;\n  const name = id.replace(/^minecraft:/, \"\");\n  let cat = CAT.misc;\n  if (TOOLS.test(name)) cat = CAT.tools;\n  else if (ARMOR.test(name)) cat = CAT.armor;\n  else if (AMMO_POTIONS.test(name)) cat = CAT.ammo;\n  else if (item.getComponent(\"minecraft:food\")) cat = CAT.food;\n  else if (MATERIALS.test(name)) cat = CAT.materials;\n  else if (MOB_DROPS.test(name)) cat = CAT.drops;\n  else if (BlockTypes.get(id)) cat = CAT.blocks;\n  catCache.set(id, cat);\n  return cat;\n}\n\n/** Splits \"minecraft:light_blue_stained_glass\" into base \"stained_glass\" + color index 11. */\nfunction colorSplit(id) {\n  const name = id.replace(/^minecraft:/, \"\");\n  for (const c of COLOR_MATCH) {\n    if (name.startsWith(c + \"_\")) return { base: name.slice(c.length + 1), color: COLORS.indexOf(c) };\n  }\n  return { base: name, color: -1 };\n}\n\n/**\n * Comparator for merged stacks: category, then base name (so colored variants\n * group up), then color order, then full id, then bigger stacks first.\n */\nexport function compareByCategory(a, b) {\n  const ca = category(a);\n  const cb = category(b);\n  if (ca !== cb) return ca - cb;\n  const sa = colorSplit(a.typeId);\n  const sb = colorSplit(b.typeId);\n  if (sa.base !== sb.base) return sa.base < sb.base ? -1 : 1;\n  if (sa.color !== sb.color) return sa.color - sb.color;\n  if (a.typeId !== b.typeId) return a.typeId < b.typeId ? -1 : 1;\n  return b.amount - a.amount;\n}\n\n/** Plain A-Z by item id, bigger stacks first. */\nexport function compareById(a, b) {\n  const byId = a.typeId < b.typeId ? -1 : a.typeId > b.typeId ? 1 : 0;\n  return byId || b.amount - a.amount;\n}\n","scripts/main.js":"import { start } from \"./core/start.js\";\nimport modules, { moduleMeta } from \"./modules/index.js\";\n\nstart(modules, moduleMeta);\n","scripts/modules/auto-fisher/index.js":"// Cast as usual; when a fish bites, the catch is reeled in for you: vanilla\n// fishing loot (rod enchantments apply), XP, and one durability point per\n// catch. You still cast every time. See docs/MODULES.md#auto-fisher.\nimport { world, system } from \"@minecraft/server\";\nimport { damageItem, getUnbreakingLevel } from \"../../lib/items.js\";\n\nconst SETTLE_TICKS = 20; // ignore the splash when the hook lands\nconst BITE_VELOCITY = -0.1; // vertical speed of the bite dip (idle bobbing stays above this)\nconst GIVE_UP_TICKS = 20 * 60 * 2; // hook left unattended for 2 minutes\n\nexport default {\n  id: \"auto-fisher\",\n  name: \"Auto fisher\",\n\n  settings: [],\n\n  register(ctx) {\n    world.afterEvents.entitySpawn.subscribe(\n      ctx.guard((ev) => {\n        const hook = ev.entity;\n        if (hook.typeId !== \"minecraft:fishing_hook\") return;\n        const player = hook.getComponent(\"minecraft:projectile\")?.owner;\n        if (!player || player.typeId !== \"minecraft:player\" || !ctx.isEnabled(player)) return;\n\n        let ticks = 0;\n        let inWater = 0;\n        const id = system.runInterval(\n          ctx.guard(() => {\n            ticks++;\n            if (!hook.isValid || !player.isValid || ticks > GIVE_UP_TICKS) return system.clearRun(id);\n            if (!hook.isInWater) return;\n            inWater++;\n            if (inWater > SETTLE_TICKS && hook.getVelocity().y < BITE_VELOCITY) {\n              system.clearRun(id);\n              reelIn(player, hook, ctx);\n            }\n          }),\n          1,\n        );\n      }),\n    );\n  },\n};\n\nfunction reelIn(player, hook, ctx) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  const slot = player.selectedSlotIndex;\n  const rod = container?.getItem(slot);\n  if (rod?.typeId !== \"minecraft:fishing_rod\") return; // not holding the rod: leave the hook alone\n\n  const table = world.getLootTableManager().getLootTable(\"gameplay/fishing\");\n  const loot = table && world.getLootTableManager().generateLootFromTable(table, rod);\n  if (!loot) return;\n\n  const spot = hook.location;\n  hook.remove();\n  for (const stack of loot) {\n    const left = container.addItem(stack);\n    if (left) player.dimension.spawnItem(left, player.location);\n  }\n  player.dimension.spawnXp(player.location, 1 + Math.floor(Math.random() * 6));\n  player.dimension.playSound?.(\"random.splash\", spot);\n\n  if (player.getGameMode() !== \"Creative\") {\n    container.setItem(slot, damageItem(rod, getUnbreakingLevel(rod)));\n  }\n  ctx.feedback(player, `Caught ${loot.map((s) => `${s.amount} ${s.typeId.replace(\"minecraft:\", \"\").replace(/_/g, \" \")}`).join(\", \") || \"nothing\"}`);\n}\n","scripts/modules/auto-replant/index.js":"// Harvesting a mature crop replants it with any tool (or bare hand), paying\n// with one seed/item from the drops, or from your inventory when the drops had\n// none (wheat drops 0 seeds ~10% of the time). No seed anywhere: no replant.\n// A fresh replant can't be broken for 2s, so a follow-up swing doesn't pop it.\n// With a hoe, the whole connected field of that crop is harvested and\n// replanted, costing real hoe durability per extra crop.\n// See docs/MODULES.md#auto-replant.\nimport { world, system, BlockPermutation, GameMode } from \"@minecraft/server\";\nimport { getUnbreakingLevel, remainingDurability, damageItem } from \"../../lib/items.js\";\nimport { protectFresh, takeFromInventory } from \"../../lib/fresh-plants.js\";\n\nconst MAX_TRIES = 8; // ticks to wait for the drops to appear\n\n// block id -> growth state name, mature value, and the dropped item that replants it.\nconst CROPS = {\n  \"minecraft:wheat\": { state: \"growth\", mature: 7, seed: \"minecraft:wheat_seeds\" },\n  \"minecraft:carrots\": { state: \"growth\", mature: 7, seed: \"minecraft:carrot\" },\n  \"minecraft:potatoes\": { state: \"growth\", mature: 7, seed: \"minecraft:potato\" },\n  \"minecraft:beetroot\": { state: \"growth\", mature: 7, seed: \"minecraft:beetroot_seeds\" },\n  \"minecraft:nether_wart\": { state: \"age\", mature: 3, seed: \"minecraft:nether_wart\" },\n};\n\n// Fields can step up/down a block (terraces), so all 26 neighbors count.\nconst NEIGHBORS = [];\nfor (let x = -1; x <= 1; x++)\n  for (let y = -1; y <= 1; y++)\n    for (let z = -1; z <= 1; z++) if (x || y || z) NEIGHBORS.push({ x, y, z });\n\nconst posKey = (l) => `${l.x},${l.y},${l.z}`;\n\n/** Removes one `seedId` from the drops near `center`. Returns true if one was found. */\nfunction takeSeed(dimension, center, seedId) {\n  const drops = dimension.getEntities({ type: \"minecraft:item\", location: center, maxDistance: 2 });\n  for (const drop of drops) {\n    const stack = drop.getComponent(\"minecraft:item\")?.itemStack;\n    if (stack?.typeId !== seedId) continue;\n    if (stack.amount > 1) {\n      const rest = stack.clone();\n      rest.amount = stack.amount - 1;\n      dimension.spawnItem(rest, drop.location);\n    }\n    drop.remove();\n    return true;\n  }\n  return false;\n}\n\nfunction plant(block, cropId, crop) {\n  block.setPermutation(BlockPermutation.resolve(cropId, { [crop.state]: 0 }));\n  protectFresh(block);\n}\n\n/** Replants the crop the player broke by hand, using a seed from its drops (or their inventory). */\nfunction replantOrigin(ctx, player, dimension, loc, cropId, crop) {\n  // Drops spawn a tick or two after the break event, so keep looking briefly.\n  const center = { x: loc.x + 0.5, y: loc.y + 0.5, z: loc.z + 0.5 };\n  const creative = player.getGameMode() === GameMode.Creative;\n  let tries = 0;\n  const attempt = () => {\n    try {\n      const block = dimension.getBlock(loc);\n      if (!block?.isAir) return;\n      if (takeSeed(dimension, center, crop.seed)) {\n        plant(block, cropId, crop);\n      } else if (++tries < MAX_TRIES) {\n        system.run(attempt);\n      } else if (creative || (player.isValid && takeFromInventory(player, crop.seed))) {\n        plant(block, cropId, crop);\n      }\n    } catch (e) {\n      ctx.log(e);\n    }\n  };\n  system.run(attempt);\n}\n\n/**\n * Walks the connected field of `cropId` (through crops of any age) and\n * harvests + replants every mature one, up to `cap`. Each harvest uses the\n * vanilla loot table with the hoe (Fortune applies), keeps one seed back to\n * replant, and spends one use of hoe durability. Stops at 1 durability left.\n * @returns {number} crops harvested (not counting the origin)\n */\nfunction harvestField(player, dimension, originLoc, cropId, crop, cap) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  let tool = container?.getItem(player.selectedSlotIndex);\n  if (!container || !tool?.typeId.endsWith(\"_hoe\")) return 0;\n\n  const creative = player.getGameMode() === GameMode.Creative;\n  const unbreaking = getUnbreakingLevel(tool);\n  const lootManager = world.getLootTableManager();\n\n  const seen = new Set([posKey(originLoc)]);\n  const queue = [originLoc];\n  let harvested = 0;\n\n  outer: while (queue.length > 0) {\n    const loc = queue.shift();\n    for (const d of NEIGHBORS) {\n      const next = { x: loc.x + d.x, y: loc.y + d.y, z: loc.z + d.z };\n      const k = posKey(next);\n      if (seen.has(k)) continue;\n      seen.add(k);\n\n      const block = dimension.getBlock(next);\n      if (!block || block.typeId !== cropId) continue;\n      queue.push(next); // young crops still connect the field\n\n      const perm = block.permutation;\n      if (perm.getState(crop.state) !== crop.mature) continue;\n      if (!creative && remainingDurability(tool) <= 1) break outer;\n\n      const loot = lootManager.generateLootFromBlockPermutation(perm, tool);\n      if (loot === undefined) continue;\n\n      // Keep one seed back for the replant; if the drops had none, use one from the inventory.\n      let replanted = false;\n      for (const stack of loot) {\n        if (!replanted && stack.typeId === crop.seed) {\n          replanted = true;\n          if (stack.amount <= 1) continue;\n          stack.amount -= 1;\n        }\n        dimension.spawnItem(stack, { x: next.x + 0.5, y: next.y + 0.5, z: next.z + 0.5 });\n      }\n      if (!replanted) replanted = creative || takeFromInventory(player, crop.seed);\n      block.setPermutation(\n        replanted ? BlockPermutation.resolve(cropId, { [crop.state]: 0 }) : BlockPermutation.resolve(\"minecraft:air\"),\n      );\n      harvested++;\n\n      if (!creative) tool = damageItem(tool, unbreaking); // protected above, never breaks\n      if (harvested >= cap - 1) break outer;\n    }\n  }\n\n  if (!creative && harvested > 0) container.setItem(player.selectedSlotIndex, tool);\n  return harvested;\n}\n\nexport default {\n  id: \"auto-replant\",\n  name: \"Auto-replant\",\n\n  settings: [\n    { key: \"field\", type: \"toggle\", label: \"Hoe harvests the whole field\", default: true },\n    { key: \"fieldSneak\", type: \"toggle\", label: \"Whole field only while sneaking\", default: false },\n    { key: \"cap\", type: \"slider\", label: \"Max crops per field\", default: 128, min: 16, max: 256, step: 16 },\n  ],\n\n  register(ctx) {\n    world.afterEvents.playerBreakBlock.subscribe((ev) => {\n      const player = ev.player;\n      if (!ctx.isEnabled(player)) return;\n      const perm = ev.brokenBlockPermutation;\n      const cropId = perm.type.id;\n      const crop = CROPS[cropId];\n      if (!crop || perm.getState(crop.state) !== crop.mature) return;\n\n      const { dimension } = ev;\n      const loc = ev.block.location;\n      replantOrigin(ctx, player, dimension, loc, cropId, crop);\n\n      const hoe = ev.itemStackBeforeBreak?.typeId.endsWith(\"_hoe\");\n      if (!hoe || !ctx.get(player, \"field\")) return;\n      if (ctx.get(player, \"fieldSneak\") && !player.isSneaking) return;\n\n      const cap = ctx.capped(player, \"cap\");\n      ctx.run(() => {\n        const n = harvestField(player, dimension, loc, cropId, crop, cap);\n        if (n > 0) ctx.feedback(player, `Harvested ${n + 1} crops`);\n      });\n    });\n  },\n};\n","scripts/modules/auto-torch/index.js":"// Auto-torch: while you hold a pickaxe and keep torches in the LAST hotbar\n// slot, a torch is placed at your feet whenever you're standing somewhere\n// dark enough for mobs to spawn. Each one comes out of that slot (creative\n// is free). Move the torches out of the last slot to stop it.\n// See docs/MODULES.md#auto-torch.\nimport { world, system, BlockPermutation, GameMode } from \"@minecraft/server\";\nimport { canStandAt, lightAt } from \"../../lib/light.js\";\n\nconst INTERVAL = 5; // ticks between checks\nconst TORCH_SLOT = 8; // last hotbar slot\nconst TORCHES = new Set([\"minecraft:torch\", \"minecraft:soul_torch\", \"minecraft:copper_torch\"]);\n\nexport default {\n  id: \"auto-torch\",\n  name: \"Auto-torch\",\n\n  settings: [\n    {\n      key: \"threshold\",\n      type: \"slider\",\n      label: \"Place when light is at or below\",\n      tooltip: \"0 = only where mobs can spawn. Higher = more torches, closer together.\",\n      default: 0,\n      min: 0,\n      max: 7,\n      step: 1,\n    },\n    { key: \"anyTool\", type: \"toggle\", label: \"Also with a shovel or axe in hand\", default: false },\n  ],\n\n  register(ctx) {\n    system.runInterval(\n      ctx.guard(() => {\n        for (const player of world.getPlayers()) {\n          if (!ctx.isEnabled(player) || !player.isOnGround || player.isSwimming) continue;\n          const mode = player.getGameMode();\n          if (mode === GameMode.Spectator) continue;\n\n          const container = player.getComponent(\"minecraft:inventory\")?.container;\n          if (!container) continue;\n          const held = container.getItem(player.selectedSlotIndex)?.typeId ?? \"\";\n          const toolOk = held.endsWith(\"_pickaxe\") || (ctx.get(player, \"anyTool\") && /_(shovel|axe)$/.test(held));\n          if (!toolOk) continue;\n          const torches = container.getItem(TORCH_SLOT);\n          if (!torches || !TORCHES.has(torches.typeId)) continue;\n\n          const dim = player.dimension;\n          const feet = { x: Math.floor(player.location.x), y: Math.floor(player.location.y), z: Math.floor(player.location.z) };\n          if (!canStandAt(dim, feet)) continue;\n          const l = lightAt(dim, feet);\n          // Under cover only (sky <= 7): out in the open, daylight would make this place torches all night.\n          if (!l || l.sky > 7 || l.total > ctx.get(player, \"threshold\")) continue;\n\n          const block = dim.getBlock(feet);\n          if (!block) continue;\n          block.setPermutation(BlockPermutation.resolve(torches.typeId, { torch_facing_direction: \"top\" }));\n          if (mode !== GameMode.Creative) {\n            if (torches.amount > 1) {\n              torches.amount -= 1;\n              container.setItem(TORCH_SLOT, torches);\n            } else {\n              container.setItem(TORCH_SLOT, undefined);\n            }\n          }\n          dim.playSound(\"dig.wood\", block.center(), { volume: 0.5, pitch: 1.4 });\n        }\n      }),\n      INTERVAL,\n    );\n  },\n};\n","scripts/modules/chunk-borders/index.js":"// Chunk borders: outlines the 16x16 chunk you're standing in with small\n// particles only you can see. Yellow corner posts, cyan edges at your feet and\n// eye level. Toggle from the menu. Needs the QoL resource pack.\n// See docs/MODULES.md#chunk-borders.\nimport { world, system, MolangVariableMap } from \"@minecraft/server\";\n\nconst INTERVAL = 20;\nconst BELOW = 4; // corner posts run from feet-4 ...\nconst ABOVE = 12; // ... to feet+12\nconst EDGE_STEP = 0.5;\n\nexport default {\n  id: \"chunk-borders\",\n  name: \"Chunk borders\",\n\n  settings: [{ key: \"show\", type: \"toggle\", label: \"Show chunk borders\", default: false }],\n\n  menu: [\n    {\n      id: \"toggle\",\n      label: \"Chunk borders on / off\",\n      run(player, ctx) {\n        const on = !ctx.get(player, \"show\");\n        ctx.set(player, \"show\", on);\n        ctx.feedback(player, on ? \"Chunk borders on\" : \"Chunk borders off\");\n      },\n    },\n  ],\n\n  register(ctx) {\n    const lifetime = (INTERVAL + 4) / 20;\n    const color = (r, g, b, a) => {\n      const m = new MolangVariableMap();\n      m.setColorRGBA(\"variable.color\", { red: r, green: g, blue: b, alpha: a });\n      m.setFloat(\"variable.lifetime\", lifetime);\n      return m;\n    };\n    const corner = color(1, 0.85, 0.1, 1);\n    const edge = color(0.2, 0.9, 1, 0.9);\n\n    system.runInterval(\n      ctx.guard(() => {\n        for (const player of world.getPlayers()) {\n          if (!ctx.isEnabled(player) || !ctx.get(player, \"show\")) continue;\n          const { x, y, z } = player.location;\n          const cx = Math.floor(x / 16) * 16;\n          const cz = Math.floor(z / 16) * 16;\n          const feet = Math.floor(y);\n          const draw = (px, py, pz, m) => {\n            try {\n              player.spawnParticle(\"qol:chunk_line\", { x: px, y: py, z: pz }, m);\n            } catch {\n              // resource pack missing or out of bounds\n            }\n          };\n          // Corner posts.\n          for (const [px, pz] of [[cx, cz], [cx + 16, cz], [cx, cz + 16], [cx + 16, cz + 16]]) {\n            for (let py = feet - BELOW; py <= feet + ABOVE; py += 0.5) draw(px, py, pz, corner);\n          }\n          // Edges at foot level and eye level.\n          for (const py of [feet + 0.05, feet + 1.6]) {\n            for (let t = EDGE_STEP; t < 16; t += EDGE_STEP) {\n              draw(cx + t, py, cz, edge);\n              draw(cx + t, py, cz + 16, edge);\n              draw(cx, py, cz + t, edge);\n              draw(cx + 16, py, cz + t, edge);\n            }\n          }\n        }\n      }),\n      INTERVAL,\n    );\n  },\n};\n","scripts/modules/death-coords/index.js":"// Posts where you died (coordinates + dimension) to your own chat.\n// See docs/MODULES.md#death-coords.\nimport { world } from \"@minecraft/server\";\n\nconst DIMENSIONS = {\n  \"minecraft:overworld\": \"Overworld\",\n  \"minecraft:nether\": \"Nether\",\n  \"minecraft:the_end\": \"End\",\n};\n\nexport default {\n  id: \"death-coords\",\n  name: \"Death coordinates\",\n\n  settings: [],\n\n  register(ctx) {\n    world.afterEvents.entityDie.subscribe(\n      ctx.guard((ev) => {\n        const player = ev.deadEntity;\n        if (player.typeId !== \"minecraft:player\" || !ctx.isEnabled(player)) return;\n        const { x, y, z } = player.location;\n        const dim = DIMENSIONS[player.dimension.id] ?? player.dimension.id;\n        player.sendMessage(`§c[QoL] You died at ${Math.floor(x)} ${Math.floor(y)} ${Math.floor(z)} (${dim})`);\n      }),\n    );\n  },\n};\n","scripts/modules/gravestone/index.js":"// Gravestone: your death drops go into a vanilla chest with a sign on top,\n// at the nearest safe spot (lava / void deaths move to safe ground). The grave\n// never drops itself (no free chests): it disappears when emptied, and breaking\n// it spills only the contents. See docs/MODULES.md#gravestone.\nimport { world, system, BlockPermutation, SignSide } from \"@minecraft/server\";\n\nconst GRAVES_KEY = \"qol:gravestone:graves\"; // world dynamic property, JSON list\nconst CLAIM_TICKS = 2; // death drops spawned within this many ticks are claimed\nconst CLAIM_RADIUS = 3;\nconst SEARCH_RADIUS = 8;\nconst SWEEP_INTERVAL = 40; // ticks between empty-grave checks\nconst SAFE_INTERVAL = 20; // ticks between last-safe-spot updates\n\nconst REPLACEABLE = new Set([\n  \"minecraft:water\",\n  \"minecraft:flowing_water\",\n  \"minecraft:short_grass\",\n  \"minecraft:tall_grass\",\n  \"minecraft:fern\",\n  \"minecraft:large_fern\",\n  \"minecraft:snow_layer\",\n  \"minecraft:deadbush\",\n  \"minecraft:fire\",\n  \"minecraft:soul_fire\",\n]);\nconst NOT_GROUND = new Set([\"minecraft:hopper\", \"minecraft:magma\", \"minecraft:lava\", \"minecraft:flowing_lava\"]);\nconst LAVA = new Set([\"minecraft:lava\", \"minecraft:flowing_lava\"]);\nconst CHESTS = new Set([\"minecraft:chest\", \"minecraft:trapped_chest\"]);\nconst CHEST_SLOTS = 27;\nconst MAX_CHESTS = 3; // a full death is 41 stacks: 2 chests; 3 is slack for odd cases\nconst HORIZONTAL = [\n  { x: 1, y: 0, z: 0 },\n  { x: -1, y: 0, z: 0 },\n  { x: 0, y: 0, z: 1 },\n  { x: 0, y: 0, z: -1 },\n];\nconst SIDES = [...HORIZONTAL, { x: 0, y: 1, z: 0 }];\n\nconst add = (a, b) => ({ x: a.x + b.x, y: a.y + b.y, z: a.z + b.z });\nconst floor = (l) => ({ x: Math.floor(l.x), y: Math.floor(l.y), z: Math.floor(l.z) });\nconst same = (a, b) => a.x === b.x && a.y === b.y && a.z === b.z;\nconst above = (l) => add(l, { x: 0, y: 1, z: 0 });\n\n/** @returns {Array<{ dim: string, chests: any[], sign: any, owner: string, name: string, locked: boolean, removeEmpty: boolean }>} */\nfunction loadGraves() {\n  try {\n    return JSON.parse(/** @type {string} */ (world.getDynamicProperty(GRAVES_KEY) ?? \"[]\"));\n  } catch {\n    return [];\n  }\n}\nfunction saveGraves(graves) {\n  world.setDynamicProperty(GRAVES_KEY, JSON.stringify(graves));\n}\n\nfunction findGrave(graves, dimId, loc) {\n  return graves.find((g) => g.dim === dimId && (g.chests.some((c) => same(c, loc)) || same(g.sign, loc)));\n}\n\nfunction safeGet(dimension, loc) {\n  try {\n    return dimension.getBlock(loc);\n  } catch {\n    return undefined; // out of world bounds\n  }\n}\n\n/**\n * Somewhere a grave chest can go: open (air/water/grass), ground under it, no\n * lava touching it, and not beside someone else's chest (it could join into a\n * double chest with it). Chests in `own` are this grave's and may be next to it.\n */\nfunction isChestSpot(dimension, loc, own = []) {\n  if (own.some((c) => same(c, loc))) return false;\n  const block = safeGet(dimension, loc);\n  if (!block || !(block.isAir || REPLACEABLE.has(block.typeId))) return false;\n  const below = safeGet(dimension, add(loc, { x: 0, y: -1, z: 0 }));\n  if (!below || below.isAir || below.isLiquid || NOT_GROUND.has(below.typeId) || REPLACEABLE.has(below.typeId)) {\n    return false;\n  }\n  for (const d of SIDES) {\n    if (LAVA.has(safeGet(dimension, add(loc, d))?.typeId ?? \"\")) return false;\n  }\n  for (const d of HORIZONTAL) {\n    const n = add(loc, d);\n    if (CHESTS.has(safeGet(dimension, n)?.typeId ?? \"\") && !own.some((c) => same(c, n))) return false;\n  }\n  return true;\n}\n\n/** The grave's first chest also needs air above it for the sign. */\nfunction isSpot(dimension, loc) {\n  return isChestSpot(dimension, loc) && !!safeGet(dimension, above(loc))?.isAir;\n}\n\n/** A free spot beside `loc` for the 2nd half of a double chest. */\nfunction sideOf(dimension, loc) {\n  return HORIZONTAL.map((d) => add(loc, d)).find((l) => isChestSpot(dimension, l, [loc]));\n}\n\n/** Nearest location to `origin` within SEARCH_RADIUS that passes `test`. */\nfunction searchNear(dimension, origin, test) {\n  const { min, max } = dimension.heightRange;\n  const start = { ...origin, y: Math.min(Math.max(origin.y, min + 1), max - 2) };\n  let best;\n  let bestDist = Infinity;\n  for (let dx = -SEARCH_RADIUS; dx <= SEARCH_RADIUS; dx++) {\n    for (let dz = -SEARCH_RADIUS; dz <= SEARCH_RADIUS; dz++) {\n      for (let dy = -4; dy <= SEARCH_RADIUS; dy++) {\n        const dist = dx * dx + dy * dy + dz * dz;\n        if (dist >= bestDist) continue;\n        const loc = add(start, { x: dx, y: dy, z: dz });\n        if (test(loc)) {\n          best = loc;\n          bestDist = dist;\n        }\n      }\n    }\n  }\n  return best;\n}\n\n/**\n * Where the grave's chests go, first one (with the sign) first. Needing more\n * than one chest, it prefers the nearest spot with room for a double chest;\n * failing that, extra chests go wherever fits nearby. Empty if nothing fits.\n */\nfunction planChests(dimension, origin, needed) {\n  if (needed >= 2) {\n    const pairAt = searchNear(dimension, origin, (l) => isSpot(dimension, l) && !!sideOf(dimension, l));\n    if (pairAt) {\n      const chests = [pairAt, sideOf(dimension, pairAt)];\n      return needed > 2 ? addLooseChests(dimension, chests, needed) : chests;\n    }\n  }\n  const first = searchNear(dimension, origin, (l) => isSpot(dimension, l));\n  return first ? addLooseChests(dimension, [first], needed) : [];\n}\n\nfunction addLooseChests(dimension, chests, needed) {\n  const sign = above(chests[0]);\n  while (chests.length < needed) {\n    const next = searchNear(dimension, chests[0], (l) => !same(l, sign) && isChestSpot(dimension, l, chests));\n    if (!next) break;\n    chests.push(next);\n  }\n  return chests;\n}\n\n/** Puts `stacks` into the chest at `loc`; returns what didn't fit. */\nfunction fillChest(dimension, loc, stacks) {\n  const block = dimension.getBlock(loc);\n  block.setType(\"minecraft:chest\");\n  const container = block.getComponent(\"minecraft:inventory\")?.container;\n  if (!container) return stacks;\n  const rest = [];\n  for (const s of stacks) {\n    const left = container.addItem(s);\n    if (left) rest.push(left);\n  }\n  return rest;\n}\n\n/**\n * Standing sign turned to face the player (front toward where they were looking\n * from), text on both sides so it reads from any angle.\n * ground_sign_direction: 0 = front faces south, 4 = west, 8 = north, 12 = east;\n * player yaw: 0 = looking south, 90 = west, 180 = north, -90 = east.\n */\nfunction placeSign(dimension, loc, name, yaw) {\n  const dir = ((Math.round((yaw + 180) / 22.5) % 16) + 16) % 16;\n  const block = dimension.getBlock(loc);\n  block.setPermutation(BlockPermutation.resolve(\"minecraft:standing_sign\", { ground_sign_direction: dir }));\n  const sign = block.getComponent(\"minecraft:sign\");\n  const text = `R.I.P.\\n${name}\\nDay ${world.getDay()}`;\n  sign?.setText(text, SignSide.Front);\n  sign?.setText(text, SignSide.Back);\n  sign?.setWaxed(true);\n}\n\n/** Removes a grave's blocks without dropping them (sign first so it doesn't pop off as an item). */\nfunction clearGrave(grave) {\n  const dimension = world.getDimension(grave.dim);\n  for (const loc of [grave.sign, ...grave.chests]) {\n    const block = safeGet(dimension, loc);\n    if (!block) continue;\n    if (loc !== grave.sign) block.getComponent(\"minecraft:inventory\")?.container?.clearAll();\n    block.setType(\"minecraft:air\");\n  }\n}\n\nexport default {\n  id: \"gravestone\",\n  name: \"Gravestone\",\n\n  settings: [\n    { key: \"locked\", type: \"toggle\", label: \"Only I can open or break my grave\", default: true },\n    { key: \"removeEmpty\", type: \"toggle\", label: \"Grave disappears once emptied\", default: true },\n  ],\n\n  register(ctx) {\n    /** @type {Map<string, { dimId: string, loc: any }>} last spot each player stood on safe ground */\n    const lastSafe = new Map();\n    /** Items spawned in the last few ticks, so a death can claim drops that spawned before or after the die event. */\n    /** @type {Array<{ entity: any, tick: number }>} */\n    let recentItems = [];\n    /** @type {Array<{ player: any, dimId: string, loc: any, tick: number, name: string, yaw: number, stacks: any[] }>} */\n    let pendingDeaths = [];\n    /** Items with nowhere to go, handed back on respawn. */\n    const heldForRespawn = new Map();\n\n    system.runInterval(\n      ctx.guard(() => {\n        for (const p of world.getPlayers()) {\n          if (!p.isOnGround) continue;\n          const feet = floor(p.location);\n          if (isSpot(p.dimension, feet)) lastSafe.set(p.id, { dimId: p.dimension.id, loc: feet });\n        }\n      }),\n      SAFE_INTERVAL,\n    );\n\n    world.afterEvents.entitySpawn.subscribe(\n      ctx.guard((ev) => {\n        if (ev.entity.typeId !== \"minecraft:item\") return;\n        const r = { entity: ev.entity, tick: system.currentTick };\n        // Claim right away if a death is waiting: lava can burn a drop within a tick.\n        for (const death of pendingDeaths) if (tryClaim(death, r)) return;\n        if (recentItems.length && r.tick - recentItems[0].tick > CLAIM_TICKS) {\n          recentItems = recentItems.filter((x) => r.tick - x.tick <= CLAIM_TICKS);\n        }\n        recentItems.push(r);\n      }),\n    );\n\n    world.afterEvents.entityDie.subscribe(\n      ctx.guard((ev) => {\n        const player = ev.deadEntity;\n        if (player.typeId !== \"minecraft:player\") return;\n        if (!ctx.isEnabled(player)) return;\n        const death = {\n          player,\n          dimId: player.dimension.id,\n          loc: { ...player.location },\n          tick: system.currentTick,\n          name: player.name,\n          yaw: player.getRotation().y,\n          stacks: [],\n        };\n        // Drops that spawned earlier this tick, before the die event.\n        for (const r of recentItems) tryClaim(death, r);\n        pendingDeaths.push(death);\n        system.runTimeout(ctx.guard(buildGraves), CLAIM_TICKS);\n      }),\n      { entityTypes: [\"minecraft:player\"] },\n    );\n\n    /** Moves the item entity into `death.stacks` if it's one of that death's drops. */\n    function tryClaim(death, r) {\n      if (Math.abs(r.tick - death.tick) > CLAIM_TICKS || !r.entity.isValid) return false;\n      if (r.entity.dimension.id !== death.dimId) return false;\n      const l = r.entity.location;\n      const d2 = (l.x - death.loc.x) ** 2 + (l.y - death.loc.y) ** 2 + (l.z - death.loc.z) ** 2;\n      if (d2 > CLAIM_RADIUS * CLAIM_RADIUS) return false;\n      const stack = r.entity.getComponent(\"minecraft:item\")?.itemStack;\n      if (!stack) return false;\n      death.stacks.push(stack);\n      r.entity.remove();\n      return true;\n    }\n\n    function buildGraves() {\n      const now = system.currentTick;\n      const due = pendingDeaths.filter((d) => now - d.tick >= CLAIM_TICKS);\n      pendingDeaths = pendingDeaths.filter((d) => now - d.tick < CLAIM_TICKS);\n      for (const death of due) buildGrave(death);\n      recentItems = recentItems.filter((r) => now - r.tick <= CLAIM_TICKS && r.entity.isValid);\n    }\n\n    function holdForRespawn(player, stacks) {\n      heldForRespawn.set(player.id, [...(heldForRespawn.get(player.id) ?? []), ...stacks]);\n    }\n\n    function buildGrave(death) {\n      let stacks = death.stacks;\n      if (stacks.length === 0) return;\n\n      const needed = Math.min(MAX_CHESTS, Math.ceil(stacks.length / CHEST_SLOTS));\n      let dimension = world.getDimension(death.dimId);\n      let chests = planChests(dimension, floor(death.loc), needed);\n      if (!chests.length) {\n        const safe = lastSafe.get(death.player.id);\n        if (safe) {\n          dimension = world.getDimension(safe.dimId);\n          chests = planChests(dimension, safe.loc, needed);\n        }\n      }\n      if (!chests.length) {\n        // Nowhere safe at all: hand everything back when they respawn.\n        holdForRespawn(death.player, stacks);\n        return;\n      }\n\n      // A double chest shares one container between its halves, so filling the\n      // 2nd half just tops up whatever room is left.\n      for (const loc of chests) {\n        if (stacks.length) stacks = fillChest(dimension, loc, stacks);\n      }\n      // Only if every chest spot nearby was taken: rather than leave items on the\n      // ground to despawn, they come back on respawn.\n      if (stacks.length) {\n        holdForRespawn(death.player, stacks);\n        if (death.player.isValid) {\n          death.player.sendMessage(`§7[QoL] Grave was full: ${stacks.length} stack(s) come back to you on respawn.`);\n        }\n      }\n\n      const spot = chests[0];\n      const sign = above(spot);\n      placeSign(dimension, sign, death.name, death.yaw);\n\n      const graves = loadGraves();\n      graves.push({\n        dim: dimension.id,\n        chests,\n        sign,\n        owner: death.player.id,\n        name: death.name,\n        locked: ctx.get(death.player, \"locked\"),\n        removeEmpty: ctx.get(death.player, \"removeEmpty\"),\n      });\n      saveGraves(graves);\n\n      if (death.player.isValid) {\n        death.player.sendMessage(\n          `§7[QoL] Your grave is at §f${spot.x}, ${spot.y}, ${spot.z}§7 (${dimension.id.replace(\"minecraft:\", \"\")}).`,\n        );\n      }\n    }\n\n    world.afterEvents.playerSpawn.subscribe(\n      ctx.guard((ev) => {\n        const held = heldForRespawn.get(ev.player.id);\n        if (!held) return;\n        heldForRespawn.delete(ev.player.id);\n        const container = ev.player.getComponent(\"minecraft:inventory\")?.container;\n        for (const s of held) {\n          // addItem returns undefined when it all fit (don't `?? s` that, it dupes).\n          const left = container ? container.addItem(s) : s;\n          if (left) ev.player.dimension.spawnItem(left, ev.player.location);\n        }\n        ctx.feedback(ev.player, \"No safe spot for a grave: items returned\");\n      }),\n    );\n\n    // Owner lock on opening.\n    world.beforeEvents.playerInteractWithBlock.subscribe(\n      ctx.guard((ev) => {\n        const grave = findGrave(loadGraves(), ev.block.dimension.id, ev.block.location);\n        if (!grave) return;\n        if (same(grave.sign, ev.block.location)) {\n          ev.cancel = true; // no sign editing\n          return;\n        }\n        if (grave.locked && grave.owner !== ev.player.id) {\n          ev.cancel = true;\n          if (ev.isFirstEvent) {\n            const p = ev.player;\n            system.run(() => ctx.feedback(p, `${grave.name}'s grave`));\n          }\n        }\n      }),\n    );\n\n    // Breaking: spill the contents, never drop the chest or sign.\n    world.beforeEvents.playerBreakBlock.subscribe(\n      ctx.guard((ev) => {\n        const dimId = ev.block.dimension.id;\n        const graves = loadGraves();\n        const grave = findGrave(graves, dimId, ev.block.location);\n        if (!grave) return;\n        ev.cancel = true;\n        const player = ev.player;\n        if (grave.locked && grave.owner !== player.id) {\n          system.run(() => ctx.feedback(player, `${grave.name}'s grave`));\n          return;\n        }\n        system.run(\n          ctx.guard(() => {\n            const dimension = world.getDimension(dimId);\n            for (const loc of grave.chests) {\n              const container = safeGet(dimension, loc)?.getComponent(\"minecraft:inventory\")?.container;\n              if (!container) continue;\n              const at = { x: loc.x + 0.5, y: loc.y + 0.5, z: loc.z + 0.5 };\n              for (let i = 0; i < container.size; i++) {\n                const item = container.getItem(i);\n                if (item) dimension.spawnItem(item, at);\n              }\n              // Both halves of a double chest return the same 54-slot container:\n              // empty it now so the other half doesn't spill everything again.\n              container.clearAll();\n            }\n            clearGrave(grave);\n            saveGraves(loadGraves().filter((g) => !same(g.sign, grave.sign) || g.dim !== grave.dim));\n          }),\n        );\n      }),\n    );\n\n    // Explosions leave graves alone (otherwise a creeper hands out a free chest).\n    world.beforeEvents.explosion.subscribe(\n      ctx.guard((ev) => {\n        const graves = loadGraves();\n        if (!graves.length) return;\n        const dimId = ev.dimension.id;\n        const blocks = ev.getImpactedBlocks();\n        const kept = blocks.filter((b) => !findGrave(graves, dimId, b.location));\n        if (kept.length !== blocks.length) ev.setImpactedBlocks(kept);\n      }),\n    );\n\n    // Empty graves disappear; graves whose blocks are gone are forgotten.\n    system.runInterval(\n      ctx.guard(() => {\n        const graves = loadGraves();\n        if (!graves.length) return;\n        let changed = false;\n        const keep = [];\n        for (const g of graves) {\n          const dimension = world.getDimension(g.dim);\n          const blocks = g.chests.map((l) => safeGet(dimension, l));\n          if (blocks.some((b) => b === undefined)) {\n            keep.push(g); // chunk not loaded: check later\n            continue;\n          }\n          if (blocks.every((b) => b.typeId !== \"minecraft:chest\")) {\n            changed = true; // gone (e.g. /setblock): forget it\n            continue;\n          }\n          const empty = blocks.every((b) => b.getComponent(\"minecraft:inventory\")?.container?.emptySlotsCount === b.getComponent(\"minecraft:inventory\")?.container?.size);\n          if (empty && g.removeEmpty) {\n            clearGrave(g);\n            changed = true;\n            continue;\n          }\n          keep.push(g);\n        }\n        if (changed) saveGraves(keep);\n      }),\n      SWEEP_INTERVAL,\n    );\n  },\n};\n","scripts/modules/hello/index.js":"// Dev-only smoke test for core: every trigger, every field type, a menu entry,\n// and a join message (proves the pack runs on a Realm). Not shipped in releases.\nimport { world, system } from \"@minecraft/server\";\nimport { getSetting, setSetting } from \"../../core/settings.js\";\n\nexport default {\n  id: \"hello\",\n  name: \"Hello (dev test)\",\n\n  settings: [\n    { key: \"greet\", type: \"toggle\", label: \"Greet on join\", default: true },\n    { key: \"pitch\", type: \"slider\", label: \"Click pitch x10\", default: 12, min: 5, max: 20, step: 1 },\n    {\n      key: \"word\",\n      type: \"dropdown\",\n      label: \"Greeting word\",\n      default: \"hello\",\n      options: [\n        { value: \"hello\", label: \"Hello\" },\n        { value: \"howdy\", label: \"Howdy\" },\n        { value: \"yo\", label: \"Yo\" },\n      ],\n    },\n  ],\n\n  menu: [\n    {\n      id: \"ping\",\n      label: \"Ping\",\n      run(player, ctx) {\n        ctx.feedback(player, \"§aPong from the menu\");\n      },\n    },\n  ],\n\n  register(ctx) {\n    // Bridge round-trip test: `npm run mc -- cmd \"scriptevent qol:ping hi\"` then wait for \"pong\".\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:ping\") return;\n      const text = `[qol] pong ${ev.message}`.trim();\n      world.sendMessage(text);\n      console.warn(text);\n    });\n\n    // Dev probe: `scriptevent qol:item` prints the first player's held-item durability numbers.\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:item\") return;\n      const p = world.getAllPlayers()[0];\n      const item = p?.getComponent(\"minecraft:inventory\")?.container?.getItem(p.selectedSlotIndex);\n      const d = item?.getComponent(\"minecraft:durability\");\n      const text = d\n        ? `[qol] ${item.typeId} damage=${d.damage} max=${d.maxDurability} chance(0)=${d.getDamageChance(0)} chance(3)=${d.getDamageChance(3)}`\n        : `[qol] no durability item in hand (${item?.typeId})`;\n      world.sendMessage(text);\n      console.warn(text);\n    });\n\n    // Dev probe: `scriptevent qol:set <module> <key> <value>` writes the first player's setting (true/false/number/string).\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:set\") return;\n      const p = world.getAllPlayers()[0];\n      const [moduleId, key, raw] = ev.message.split(\" \");\n      const value = raw === \"true\" ? true : raw === \"false\" ? false : Number.isNaN(Number(raw)) ? raw : Number(raw);\n      try {\n        world.sendMessage(`[qol] set ${moduleId}.${key} -> ${setSetting(p, moduleId, key, value)}`);\n      } catch (e) {\n        world.sendMessage(`[qol] set failed: ${e}`);\n      }\n    });\n\n    // Dev probe: `scriptevent qol:dump self|<x> <y> <z>` prints non-empty slots as slot:item*count.\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:dump\") return;\n      const p = world.getAllPlayers()[0];\n      const [x, y, z] = ev.message.split(\" \").map(Number);\n      const container =\n        ev.message.trim() === \"self\"\n          ? p?.getComponent(\"minecraft:inventory\")?.container\n          : p?.dimension.getBlock({ x, y, z })?.getComponent(\"minecraft:inventory\")?.container;\n      if (!container) return world.sendMessage(\"[qol] dump: no container\");\n      const parts = [];\n      for (let i = 0; i < container.size; i++) {\n        const item = container.getItem(i);\n        if (item) parts.push(`${i}:${item.typeId.replace(\"minecraft:\", \"\")}*${item.amount}`);\n      }\n      world.sendMessage(`[qol] dump size=${container.size} ${parts.join(\" \")}`);\n    });\n\n    world.afterEvents.playerSpawn.subscribe((ev) => {\n      if (!ev.initialSpawn) return;\n      const p = ev.player;\n      try {\n        if (!ctx.isEnabled(p) || !ctx.get(p, \"greet\")) return;\n        const word = ctx.get(p, \"word\");\n        p.sendMessage(`§e[QoL] ${word}, ${p.name}! Add-on is running. Clock = menu, sneak+clock = test.`);\n      } catch (e) {\n        ctx.log(e);\n      }\n    });\n  },\n};\n","scripts/modules/hotbar-swap/index.js":"// Rotates the hotbar through the enabled inventory rows:\n// hotbar <- row A <- row B <- ... <- old hotbar. Repeated use cycles back to\n// where you started. Triggers: compass in air, or double-tap sneak (opt-in) so\n// it still works with the compass in your offhand. The clock menu can move the\n// compass in/out of the offhand slot. See docs/MODULES.md#hotbar-swap.\nimport { EntityComponentTypes, EquipmentSlot } from \"@minecraft/server\";\nimport { getPlayerContainer } from \"../../lib/containers.js\";\n\nconst COMPASS = \"minecraft:compass\";\n\n// Main inventory is slots 9-35. Row 1 is the one right above the hotbar.\nconst ROWS = [\n  { key: \"row1\", label: \"Use row 1 (just above hotbar)\", start: 27 },\n  { key: \"row2\", label: \"Use row 2 (middle)\", start: 18 },\n  { key: \"row3\", label: \"Use row 3 (top)\", start: 9 },\n];\n\n/** @param {import(\"@minecraft/server\").Player} player */\nfunction getEquippable(player) {\n  return /** @type {import(\"@minecraft/server\").EntityEquippableComponent | undefined} */ (\n    player.getComponent(EntityComponentTypes.Equippable)\n  );\n}\n\n/**\n * Compass in inventory -> offhand (whatever was in the offhand takes its slot).\n * Compass already in offhand -> back into the inventory.\n */\nfunction toggleOffhandCompass(player, ctx) {\n  const container = getPlayerContainer(player);\n  const equip = getEquippable(player);\n  if (!container || !equip) return;\n  const offhand = equip.getEquipment(EquipmentSlot.Offhand);\n\n  if (offhand?.typeId === COMPASS) {\n    const leftover = container.addItem(offhand);\n    if (leftover) {\n      ctx.feedback(player, \"Inventory full\");\n      return;\n    }\n    equip.setEquipment(EquipmentSlot.Offhand, undefined);\n    ctx.feedback(player, \"Compass back in inventory\");\n    return;\n  }\n\n  let slot = -1;\n  for (let i = 0; i < container.size; i++) {\n    if (container.getItem(i)?.typeId === COMPASS) {\n      slot = i;\n      break;\n    }\n  }\n  if (slot < 0) {\n    ctx.feedback(player, \"No compass in inventory\");\n    return;\n  }\n\n  const compass = container.getItem(slot);\n  if (!equip.setEquipment(EquipmentSlot.Offhand, compass)) {\n    ctx.feedback(player, \"Couldn't move the compass\");\n    return;\n  }\n  container.setItem(slot, offhand); // old offhand item (or nothing) takes the compass's spot\n  ctx.feedback(player, \"Compass in offhand\");\n}\n\nexport default {\n  id: \"hotbar-swap\",\n  name: \"Hotbar swap\",\n\n  settings: [\n    ...ROWS.map((r) => ({ key: r.key, type: \"toggle\", label: r.label, default: true })),\n    { key: \"doubleTapSneak\", type: \"toggle\", label: \"Double-tap sneak to swap hotbar\", default: false },\n  ],\n\n  menu: [\n    {\n      id: \"compass-offhand\",\n      label: \"Compass to/from offhand\",\n      run(player, ctx) {\n        toggleOffhandCompass(player, ctx);\n      },\n    },\n  ],\n\n  register(ctx) {\n    const swap = (player, keepHeld) => {\n      const container = getPlayerContainer(player);\n      if (!container) return;\n\n      const starts = [0, ...ROWS.filter((r) => ctx.get(player, r.key)).map((r) => r.start)];\n      if (starts.length < 2) {\n        ctx.feedback(player, \"No rows enabled\");\n        return;\n      }\n\n      // Compass use keeps the held column put so the compass stays in your hand.\n      const held = keepHeld ? player.selectedSlotIndex : -1;\n      const snapshot = starts.map((start) => {\n        const row = [];\n        for (let i = 0; i < 9; i++) row.push(container.getItem(start + i));\n        return row;\n      });\n      starts.forEach((start, j) => {\n        const incoming = snapshot[(j + 1) % starts.length];\n        for (let i = 0; i < 9; i++) {\n          if (i !== held) container.setItem(start + i, incoming[i]);\n        }\n      });\n\n      ctx.feedback(player, \"Hotbar swapped\");\n    };\n\n    ctx.on(\"compass:air\", (player) => swap(player, true));\n    ctx.on(\"sneak:double\", (player) => {\n      if (ctx.get(player, \"doubleTapSneak\")) swap(player, false);\n    });\n  },\n};\n","scripts/modules/index.js":"// GENERATED by tools/gen-index.mjs from modules.json. Do not edit by hand.\nimport hello from \"./hello/index.js\";\nimport veinminer from \"./veinminer/index.js\";\nimport treeFelling from \"./tree-felling/index.js\";\nimport autoFisher from \"./auto-fisher/index.js\";\nimport autoReplant from \"./auto-replant/index.js\";\nimport toolWarning from \"./tool-warning/index.js\";\nimport deathCoords from \"./death-coords/index.js\";\nimport sorting from \"./sorting/index.js\";\nimport hotbarSwap from \"./hotbar-swap/index.js\";\nimport gravestone from \"./gravestone/index.js\";\nimport restock from \"./restock/index.js\";\nimport sleep from \"./sleep/index.js\";\nimport lightOverlay from \"./light-overlay/index.js\";\nimport chunkBorders from \"./chunk-borders/index.js\";\nimport autoTorch from \"./auto-torch/index.js\";\n\nexport const moduleMeta = {\n  \"hello\": {\n    \"name\": \"Hello (dev test)\",\n    \"default\": true\n  },\n  \"veinminer\": {\n    \"name\": \"Veinminer\",\n    \"default\": true\n  },\n  \"tree-felling\": {\n    \"name\": \"Tree felling\",\n    \"default\": true\n  },\n  \"auto-fisher\": {\n    \"name\": \"Auto fisher\",\n    \"default\": true\n  },\n  \"auto-replant\": {\n    \"name\": \"Auto-replant\",\n    \"default\": true\n  },\n  \"tool-warning\": {\n    \"name\": \"Tool warning\",\n    \"default\": true\n  },\n  \"death-coords\": {\n    \"name\": \"Death coordinates\",\n    \"default\": true\n  },\n  \"sorting\": {\n    \"name\": \"Sorting\",\n    \"default\": true\n  },\n  \"hotbar-swap\": {\n    \"name\": \"Hotbar swap\",\n    \"default\": true\n  },\n  \"gravestone\": {\n    \"name\": \"Gravestone\",\n    \"default\": true\n  },\n  \"restock\": {\n    \"name\": \"Auto-restock hotbar\",\n    \"default\": true\n  },\n  \"sleep\": {\n    \"name\": \"One-player sleep\",\n    \"default\": true\n  },\n  \"light-overlay\": {\n    \"name\": \"Light overlay\",\n    \"default\": true\n  },\n  \"chunk-borders\": {\n    \"name\": \"Chunk borders\",\n    \"default\": true\n  },\n  \"auto-torch\": {\n    \"name\": \"Auto-torch\",\n    \"default\": true\n  }\n};\n\nexport default [hello, veinminer, treeFelling, autoFisher, autoReplant, toolWarning, deathCoords, sorting, hotbarSwap, gravestone, restock, sleep, lightOverlay, chunkBorders, autoTorch];\n","scripts/modules/light-overlay/index.js":"// Light overlay: marks floor spots where hostile mobs can spawn, around you,\n// with a flat colored particle only you can see. Red = spawns any time (dark,\n// under cover), yellow = spawns at night (dark, open sky). Shows while you\n// hold a torch, or always if you flip it on from the menu. Needs the QoL\n// resource pack for the marker particle. See docs/MODULES.md#light-overlay.\nimport { world, system, MolangVariableMap, EquipmentSlot } from \"@minecraft/server\";\nimport { spawnState, lightAt } from \"../../lib/light.js\";\n\nconst INTERVAL = 20; // ticks between redraws; marker lifetime is a bit longer, so no flicker\nconst LIGHT_ITEMS = /(^|:)(torch|soul_torch|copper_torch|lantern|soul_lantern|copper_lantern)$/;\nconst COLORS = {\n  always: { red: 1, green: 0.15, blue: 0.15, alpha: 0.85 },\n  night: { red: 1, green: 0.85, blue: 0.1, alpha: 0.7 },\n};\n\nfunction holdingLight(player) {\n  const eq = player.getComponent(\"minecraft:equippable\");\n  const ids = [eq?.getEquipment(EquipmentSlot.Mainhand)?.typeId, eq?.getEquipment(EquipmentSlot.Offhand)?.typeId];\n  return ids.some((id) => id && LIGHT_ITEMS.test(id));\n}\n\nexport default {\n  id: \"light-overlay\",\n  name: \"Light overlay\",\n\n  settings: [\n    { key: \"always\", type: \"toggle\", label: \"Always on (not just while holding a torch)\", default: false },\n    { key: \"radius\", type: \"slider\", label: \"Radius (blocks)\", default: 6, min: 3, max: 10, step: 1 },\n  ],\n\n  menu: [\n    {\n      id: \"toggle\",\n      label: \"Light overlay: always on / off\",\n      run(player, ctx) {\n        const on = !ctx.get(player, \"always\");\n        ctx.set(player, \"always\", on);\n        ctx.feedback(player, on ? \"Light overlay always on\" : \"Light overlay: only while holding a torch\");\n      },\n    },\n  ],\n\n  register(ctx) {\n    const markers = Object.fromEntries(\n      Object.entries(COLORS).map(([k, c]) => {\n        const m = new MolangVariableMap();\n        m.setColorRGBA(\"variable.color\", c);\n        m.setFloat(\"variable.lifetime\", (INTERVAL + 4) / 20);\n        return [k, m];\n      }),\n    );\n\n    system.runInterval(\n      ctx.guard(() => {\n        for (const player of world.getPlayers()) {\n          if (!ctx.isEnabled(player)) continue;\n          if (!ctx.get(player, \"always\") && !holdingLight(player)) continue;\n          const r = ctx.get(player, \"radius\");\n          const dim = player.dimension;\n          const base = { x: Math.floor(player.location.x), y: Math.floor(player.location.y), z: Math.floor(player.location.z) };\n          for (let dx = -r; dx <= r; dx++) {\n            for (let dz = -r; dz <= r; dz++) {\n              if (dx * dx + dz * dz > r * r) continue;\n              for (let dy = -4; dy <= 3; dy++) {\n                const loc = { x: base.x + dx, y: base.y + dy, z: base.z + dz };\n                const state = spawnState(dim, loc);\n                if (!state) continue;\n                try {\n                  player.spawnParticle(\"qol:light_marker\", { x: loc.x + 0.5, y: loc.y + 0.02, z: loc.z + 0.5 }, markers[state]);\n                } catch {\n                  // resource pack missing or chunk edge: skip quietly\n                }\n              }\n            }\n          }\n        }\n      }),\n      INTERVAL,\n    );\n\n    // Calibration: `/scriptevent qol:light` prints the light where you stand.\n    system.afterEvents.scriptEventReceive.subscribe(\n      ctx.guard((ev) => {\n        if (ev.id !== \"qol:light\") return;\n        const p = ev.sourceEntity;\n        if (!p || p.typeId !== \"minecraft:player\") return;\n        const loc = { x: Math.floor(p.location.x), y: Math.floor(p.location.y), z: Math.floor(p.location.z) };\n        const l = lightAt(p.dimension, loc);\n        const text = `[qol] light at ${loc.x},${loc.y},${loc.z}: total ${l?.total} sky ${l?.sky} -> ${spawnState(p.dimension, loc) ?? \"no spawns\"}`;\n        world.sendMessage(text);\n        console.warn(text);\n      }),\n    );\n  },\n};\n","scripts/modules/restock/index.js":"// Refills an emptied hotbar slot from the rest of your inventory: a broken\n// tool or a used-up block stack gets swapped for a matching one you're\n// still carrying. See docs/MODULES.md#restock.\n//\n// Only refills when the held slot empties right after you *used* the item\n// (placed, ate, threw, swung, mined, used on a block). Moving a stack out of\n// the hotbar (quick move, dragging, dropping) isn't a use, so it's left alone.\nimport { world, system, PlayerInventoryType } from \"@minecraft/server\";\nimport { getPlayerContainer, playerRange } from \"../../lib/containers.js\";\n\nconst USE_WINDOW = 3; // ticks between the use and the slot emptying\n\nexport default {\n  id: \"restock\",\n  name: \"Auto-restock hotbar\",\n\n  settings: [],\n\n  register(ctx) {\n    /** @type {Map<string, number>} player id -> tick of their last item use */\n    const lastUse = new Map();\n    const used = (player) => {\n      if (player?.typeId === \"minecraft:player\") lastUse.set(player.id, system.currentTick);\n    };\n\n    world.afterEvents.itemUse.subscribe((ev) => used(ev.source));\n    world.afterEvents.itemCompleteUse.subscribe((ev) => used(ev.source));\n    world.afterEvents.itemReleaseUse.subscribe((ev) => used(ev.source));\n    world.afterEvents.playerPlaceBlock.subscribe((ev) => used(ev.player));\n    world.afterEvents.playerBreakBlock.subscribe((ev) => used(ev.player));\n    world.afterEvents.playerInteractWithBlock.subscribe((ev) => used(ev.player));\n    world.afterEvents.entityHitEntity.subscribe((ev) => used(ev.damagingEntity));\n    world.afterEvents.entityHitBlock.subscribe((ev) => used(ev.damagingEntity));\n    world.afterEvents.playerLeave.subscribe((ev) => lastUse.delete(ev.playerId));\n\n    world.afterEvents.playerInventoryItemChange.subscribe(\n      (ev) => {\n        const player = ev.player;\n        if (!ctx.isEnabled(player)) return;\n        if (ev.inventoryType !== PlayerInventoryType.Hotbar) return;\n        if (ev.itemStack || !ev.beforeItemStack) return; // slot still has something, or was already empty\n        if (ev.slot !== player.selectedSlotIndex) return; // only the slot in your hand gets used up\n        if (system.currentTick - (lastUse.get(player.id) ?? -Infinity) > USE_WINDOW) return; // moved, not used\n\n        const typeId = ev.beforeItemStack.typeId;\n        ctx.run(() => {\n          const container = getPlayerContainer(player);\n          if (!container || container.getItem(ev.slot)) return; // something already filled it since\n\n          const [from, to] = playerRange(false);\n          for (let i = from; i < to; i++) {\n            if (container.getItem(i)?.typeId === typeId) {\n              container.moveItem(i, ev.slot, container);\n              return;\n            }\n          }\n        });\n      },\n      { allowedSlots: [0, 1, 2, 3, 4, 5, 6, 7, 8] },\n    );\n  },\n};\n","scripts/modules/sleep/index.js":"// One-player sleep: sets the vanilla playersSleepingPercentage game rule from\n// the world owner's pack setting (default 1% = any one player skips the night).\n// World-wide by nature, so it has no per-player settings: the world owner turns\n// it on/off and sets the % on the Behavior Packs screen. Turning it off puts\n// back whatever the rule was before this pack changed it.\nimport { world, system } from \"@minecraft/server\";\n\nconst ORIGINAL_KEY = \"qol:sleep:original\"; // world dynamic property\nconst DEFAULT_PERCENT = 1;\nconst CHECK_INTERVAL = 100; // ticks: picks up pack-setting changes without a restart\n\nexport default {\n  id: \"sleep\",\n  name: \"One-player sleep\",\n  worldOnly: true,\n\n  register(ctx) {\n    const apply = () => {\n      const rules = world.gameRules;\n      const allowed = ctx.worldAllows();\n      const saved = world.getDynamicProperty(ORIGINAL_KEY);\n      if (allowed) {\n        const limit = ctx.world(\"percent\");\n        const want = typeof limit === \"number\" ? limit : DEFAULT_PERCENT;\n        if (saved === undefined) world.setDynamicProperty(ORIGINAL_KEY, rules.playersSleepingPercentage);\n        if (rules.playersSleepingPercentage !== want) rules.playersSleepingPercentage = want;\n      } else if (typeof saved === \"number\") {\n        rules.playersSleepingPercentage = saved;\n        world.setDynamicProperty(ORIGINAL_KEY, undefined);\n      }\n    };\n    system.runInterval(ctx.guard(apply), CHECK_INTERVAL);\n  },\n};\n","scripts/modules/sorting/index.js":"// Instant sorting: sneak + clock in air sorts your inventory, sneak + clock on a\n// chest (or sneak + empty hand on a chest) sorts it, optional double-tap sneak. No forms. See docs/MODULES.md#sorting.\nimport { getBlockContainer, getPlayerContainer, isStorageBlock, playerRange, sortRange } from \"../../lib/containers.js\";\n\nexport default {\n  id: \"sorting\",\n  name: \"Sorting\",\n\n  settings: [\n    {\n      key: \"mode\",\n      type: \"dropdown\",\n      label: \"Sort order\",\n      default: \"category\",\n      options: [\n        { value: \"category\", label: \"Category (tools, armor, food, blocks... colors grouped)\" },\n        { value: \"alpha\", label: \"Alphabetical (by item id)\" },\n      ],\n    },\n    { key: \"includeHotbar\", type: \"toggle\", label: \"Include hotbar when sorting inventory\", default: false },\n    { key: \"doubleTapSneak\", type: \"toggle\", label: \"Double-tap sneak to sort inventory\", default: false },\n    { key: \"emptyHand\", type: \"toggle\", label: \"Sneak + empty hand sorts containers\", default: true },\n  ],\n\n  register(ctx) {\n    const sortInventory = (player) => {\n      const container = getPlayerContainer(player);\n      if (!container) return;\n      const [from, to] = playerRange(ctx.get(player, \"includeHotbar\"));\n      sortRange(container, from, to, ctx.get(player, \"mode\"));\n      ctx.feedback(player, \"Inventory sorted\");\n    };\n\n    ctx.on(\"clock:air:sneak\", sortInventory);\n\n    ctx.on(\"sneak:double\", (player) => {\n      if (ctx.get(player, \"doubleTapSneak\")) sortInventory(player);\n    });\n\n    const sortContainer = (player, block) => {\n      const container = getBlockContainer(block);\n      if (!container || !isStorageBlock(block)) {\n        ctx.feedback(player, \"Can't sort that\");\n        return;\n      }\n      sortRange(container, 0, container.size, ctx.get(player, \"mode\"));\n      ctx.feedback(player, \"Container sorted\");\n    };\n\n    ctx.on(\"clock:container:sneak\", sortContainer);\n    ctx.on(\"hand:container:sneak\", sortContainer, (player, block) => ctx.get(player, \"emptyHand\") && isStorageBlock(block));\n  },\n};\n","scripts/modules/tool-warning/index.js":"// Sound + actionbar warning once when the held tool drops to the threshold.\n// See docs/MODULES.md#tool-warning.\nimport { world, system } from \"@minecraft/server\";\n\nconst CHECK_TICKS = 10;\n\nexport default {\n  id: \"tool-warning\",\n  name: \"Tool warning\",\n\n  settings: [\n    { key: \"percent\", type: \"slider\", label: \"Warn at % durability left\", default: 10, min: 5, max: 30, step: 5 },\n  ],\n\n  register(ctx) {\n    // playerId -> \"<typeId>:<slot>\" of the item already warned about\n    const warned = new Map();\n\n    system.runInterval(\n      ctx.guard(() => {\n        for (const player of world.getAllPlayers()) {\n          if (!ctx.isEnabled(player)) continue;\n          const slot = player.selectedSlotIndex;\n          const item = player.getComponent(\"minecraft:inventory\")?.container?.getItem(slot);\n          const durability = item?.getComponent(\"minecraft:durability\");\n          if (!durability || durability.unbreakable || durability.damage === 0) {\n            warned.delete(player.id);\n            continue;\n          }\n\n          const left = durability.maxDurability - durability.damage;\n          const low = (left / durability.maxDurability) * 100 <= ctx.get(player, \"percent\");\n          const key = `${item.typeId}:${slot}`;\n          if (!low) {\n            warned.delete(player.id);\n          } else if (warned.get(player.id) !== key) {\n            warned.set(player.id, key);\n            ctx.feedback(player, `§cYour tool is about to break (${left} uses left)`, {\n              sound: \"note.bass\",\n              pitch: 0.8,\n              volume: 1,\n            });\n          }\n        }\n      }),\n      CHECK_TICKS,\n    );\n\n    world.afterEvents.playerLeave.subscribe((ev) => warned.delete(ev.playerId));\n  },\n};\n","scripts/modules/tree-felling/index.js":"// Sneak + break a log with an axe: fells the whole trunk, paying real\n// durability. Leaves are left to decay the vanilla way. Optionally replants a\n// matching sapling at the base, taken from the player's inventory.\n// See docs/MODULES.md#tree-felling.\nimport { world, GameMode } from \"@minecraft/server\";\nimport { bulkBreak } from \"../../lib/bulk-break.js\";\nimport { protectFresh, takeFromInventory } from \"../../lib/fresh-plants.js\";\n\n// Stems that aren't tree trunks (crops), so \"_log\"/\"_stem\" alone isn't enough.\nconst NOT_TRUNKS = new Set([\n  \"minecraft:melon_stem\",\n  \"minecraft:attached_melon_stem\",\n  \"minecraft:pumpkin_stem\",\n  \"minecraft:attached_pumpkin_stem\",\n  \"minecraft:mushroom_stem\",\n]);\n\n// Trunk type -> what replants it.\nconst SAPLINGS = {\n  \"minecraft:oak_log\": \"minecraft:oak_sapling\",\n  \"minecraft:spruce_log\": \"minecraft:spruce_sapling\",\n  \"minecraft:birch_log\": \"minecraft:birch_sapling\",\n  \"minecraft:jungle_log\": \"minecraft:jungle_sapling\",\n  \"minecraft:acacia_log\": \"minecraft:acacia_sapling\",\n  \"minecraft:dark_oak_log\": \"minecraft:dark_oak_sapling\",\n  \"minecraft:pale_oak_log\": \"minecraft:pale_oak_sapling\",\n  \"minecraft:cherry_log\": \"minecraft:cherry_sapling\",\n  \"minecraft:mangrove_log\": \"minecraft:mangrove_propagule\",\n  \"minecraft:crimson_stem\": \"minecraft:crimson_fungus\",\n  \"minecraft:warped_stem\": \"minecraft:warped_fungus\",\n};\n\nconst SOIL = new Set([\n  \"minecraft:grass_block\",\n  \"minecraft:dirt\",\n  \"minecraft:coarse_dirt\",\n  \"minecraft:podzol\",\n  \"minecraft:rooted_dirt\",\n  \"minecraft:moss_block\",\n  \"minecraft:mud\",\n  \"minecraft:muddy_mangrove_roots\",\n  \"minecraft:mycelium\",\n  \"minecraft:crimson_nylium\",\n  \"minecraft:warped_nylium\",\n  \"minecraft:soul_soil\",\n]);\n\nconst MAX_DROP = 32; // how far below the chopped log to look for the ground\n\n/**\n * Plants one matching sapling where the trunk stood: straight down from the\n * chopped log through the (now air) trunk to the first soil block. Uses a\n * sapling from the player's inventory; none means no replant.\n * @returns {boolean} planted\n */\nfunction replantSapling(player, dimension, originLoc, saplingId) {\n  let ground;\n  for (let dy = 1; dy <= MAX_DROP; dy++) {\n    const below = dimension.getBlock({ x: originLoc.x, y: originLoc.y - dy, z: originLoc.z });\n    if (!below) return false;\n    if (below.isAir) continue;\n    if (!SOIL.has(below.typeId)) return false;\n    ground = below;\n    break;\n  }\n  const spot = ground?.above();\n  if (!spot?.isAir) return false;\n\n  const creative = player.getGameMode() === GameMode.Creative;\n  if (!creative && !takeFromInventory(player, saplingId)) return false;\n  spot.setType(saplingId);\n  // You're usually still swinging at the base: don't let that pop the sapling off.\n  protectFresh(spot);\n  return true;\n}\n\nfunction isTrunk(typeId) {\n  return (typeId.endsWith(\"_log\") || typeId.endsWith(\"_stem\")) && !NOT_TRUNKS.has(typeId);\n}\n\nexport default {\n  id: \"tree-felling\",\n  name: \"Tree felling\",\n\n  settings: [\n    { key: \"requireSneak\", type: \"toggle\", label: \"Require sneak\", default: true },\n    { key: \"cap\", type: \"slider\", label: \"Max blocks\", default: 128, min: 16, max: 128, step: 16 },\n    { key: \"replant\", type: \"toggle\", label: \"Replant a sapling from your inventory\", default: true },\n  ],\n\n  register(ctx) {\n    world.afterEvents.playerBreakBlock.subscribe((ev) => {\n      if (!ctx.isEnabled(ev.player)) return;\n      const tool = ev.itemStackBeforeBreak;\n      if (!tool || !tool.typeId.endsWith(\"_axe\")) return;\n      const originTypeId = ev.brokenBlockPermutation.type.id;\n      if (!isTrunk(originTypeId)) return;\n      if (ctx.get(ev.player, \"requireSneak\") && !ev.player.isSneaking) return;\n\n      const cap = ctx.capped(ev.player, \"cap\");\n      const replant = ctx.get(ev.player, \"replant\");\n\n      ctx.run(() => {\n        const origin = ev.dimension.getBlock(ev.block.location);\n        if (!origin) return;\n        const { broken } = bulkBreak({\n          player: ev.player,\n          origin,\n          originKey: originTypeId,\n          key: (id) => id,\n          cap,\n          protectTool: true, // not exposed as a setting: tree-felling never breaks the tool\n        });\n        // Stripped logs fell too, but map back to the plain log for the sapling.\n        const saplingId = SAPLINGS[originTypeId.replace(\"stripped_\", \"\")];\n        const planted = replant && saplingId && replantSapling(ev.player, ev.dimension, ev.block.location, saplingId);\n        if (broken > 0 || planted) {\n          ctx.feedback(ev.player, `Felled ${broken + 1} logs${planted ? \", sapling planted\" : \"\"}`);\n        }\n      });\n    });\n  },\n};\n","scripts/modules/veinminer/index.js":"// Sneak + break an ore with a pickaxe: flood-fills the vein, paying real\n// durability. See docs/MODULES.md#veinminer.\nimport { world } from \"@minecraft/server\";\nimport { bulkBreak } from \"../../lib/bulk-break.js\";\n\n// coal 0–2, diamond/emerald 3–7, lapis/quartz 2–5, redstone 1–5, nether gold 0–1.\n// copper/iron/gold/ancient debris are left out: no XP in vanilla.\nconst ORE_XP = [\n  { test: (id) => id === \"minecraft:coal_ore\", range: [0, 2] },\n  { test: (id) => id === \"minecraft:diamond_ore\" || id === \"minecraft:emerald_ore\", range: [3, 7] },\n  { test: (id) => id === \"minecraft:lapis_ore\" || id === \"minecraft:quartz_ore\", range: [2, 5] },\n  { test: (id) => id === \"minecraft:redstone_ore\", range: [1, 5] },\n  { test: (id) => id === \"minecraft:nether_gold_ore\", range: [0, 1] },\n];\n\n// Deepslate/lit variants are the same ore for flood-fill purposes.\nfunction oreKey(typeId) {\n  return typeId.replace(/^minecraft:(lit_)?(deepslate_)?/, \"minecraft:\");\n}\n\n// Only these trigger veinminer (after oreKey normalizes deepslate/lit\n// variants away). Plain stone/deepslate must never flood-fill.\nconst ORE_BLOCK_IDS = new Set([\n  \"minecraft:coal_ore\",\n  \"minecraft:iron_ore\",\n  \"minecraft:copper_ore\",\n  \"minecraft:gold_ore\",\n  \"minecraft:redstone_ore\",\n  \"minecraft:lapis_ore\",\n  \"minecraft:diamond_ore\",\n  \"minecraft:emerald_ore\",\n  \"minecraft:quartz_ore\",\n  \"minecraft:nether_gold_ore\",\n  \"minecraft:ancient_debris\",\n]);\n\nfunction xpFor(block, hasSilkTouch) {\n  if (hasSilkTouch) return 0;\n  const entry = ORE_XP.find((e) => e.test(oreKey(block.permutation.type.id)));\n  if (!entry) return 0;\n  const [min, max] = entry.range;\n  return min + Math.floor(Math.random() * (max - min + 1));\n}\n\nexport default {\n  id: \"veinminer\",\n  name: \"Veinminer\",\n\n  settings: [\n    { key: \"requireSneak\", type: \"toggle\", label: \"Require sneak\", default: true },\n    { key: \"cap\", type: \"slider\", label: \"Max blocks\", default: 64, min: 8, max: 64, step: 8 },\n    { key: \"protectTool\", type: \"toggle\", label: \"Never break tool\", default: true },\n  ],\n\n  register(ctx) {\n    world.afterEvents.playerBreakBlock.subscribe((ev) => {\n      if (!ctx.isEnabled(ev.player)) return;\n      const tool = ev.itemStackBeforeBreak;\n      if (!tool || !tool.typeId.endsWith(\"_pickaxe\")) return;\n      if (ctx.get(ev.player, \"requireSneak\") && !ev.player.isSneaking) return;\n\n      const originTypeId = ev.brokenBlockPermutation.type.id;\n      const originKey = oreKey(originTypeId);\n      if (!ORE_BLOCK_IDS.has(originKey)) return;\n      const hasSilkTouch = !!tool.getComponent(\"minecraft:enchantable\")?.getEnchantment(\"silk_touch\");\n      const cap = ctx.capped(ev.player, \"cap\");\n      const protectTool = ctx.get(ev.player, \"protectTool\");\n\n      ctx.run(() => {\n        const origin = ev.dimension.getBlock(ev.block.location);\n        if (!origin) return;\n        const { broken } = bulkBreak({\n          player: ev.player,\n          origin,\n          originKey,\n          key: oreKey,\n          cap,\n          protectTool,\n          xp: (block) => xpFor(block, hasSilkTouch),\n        });\n        if (broken > 0) ctx.feedback(ev.player, `Mined ${broken + 1} blocks`);\n      });\n    });\n  },\n};\n"},"resourcePack":{"manifest.json":"{\n  \"format_version\": 2,\n  \"header\": {\n    \"name\": \"QoL Add-on Overlays\",\n    \"description\": \"Particles for the QoL add-on: light level markers and chunk borders.\",\n    \"uuid\": \"c314a447-8032-462a-bb1d-33b48aa6c4ef\",\n    \"version\": [0, 3, 0],\n    \"min_engine_version\": [1, 26, 60]\n  },\n  \"modules\": [\n    {\n      \"type\": \"resources\",\n      \"uuid\": \"45acac55-ba90-4fe2-b2f8-82815977df99\",\n      \"version\": [0, 3, 0]\n    }\n  ]\n}\n","particles/chunk_line.json":"{\n  \"format_version\": \"1.10.0\",\n  \"particle_effect\": {\n    \"description\": {\n      \"identifier\": \"qol:chunk_line\",\n      \"basic_render_parameters\": {\n        \"material\": \"particles_blend\",\n        \"texture\": \"textures/particle/particles\"\n      }\n    },\n    \"components\": {\n      \"minecraft:emitter_rate_instant\": { \"num_particles\": 1 },\n      \"minecraft:emitter_lifetime_once\": { \"active_time\": 0 },\n      \"minecraft:emitter_shape_point\": {},\n      \"minecraft:particle_lifetime_expression\": { \"max_lifetime\": \"variable.lifetime ?? 1.1\" },\n      \"minecraft:particle_appearance_billboard\": {\n        \"size\": [0.07, 0.07],\n        \"facing_camera_mode\": \"rotate_xyz\",\n        \"uv\": {\n          \"texture_width\": 128,\n          \"texture_height\": 128,\n          \"uv\": [56, 0],\n          \"uv_size\": [8, 8]\n        }\n      },\n      \"minecraft:particle_appearance_tinting\": {\n        \"color\": [\"variable.color.r ?? 0.2\", \"variable.color.g ?? 0.9\", \"variable.color.b ?? 1\", \"variable.color.a ?? 0.9\"]\n      }\n    }\n  }\n}\n","particles/light_marker.json":"{\n  \"format_version\": \"1.10.0\",\n  \"particle_effect\": {\n    \"description\": {\n      \"identifier\": \"qol:light_marker\",\n      \"basic_render_parameters\": {\n        \"material\": \"particles_blend\",\n        \"texture\": \"textures/particle/particles\"\n      }\n    },\n    \"components\": {\n      \"minecraft:emitter_rate_instant\": { \"num_particles\": 1 },\n      \"minecraft:emitter_lifetime_once\": { \"active_time\": 0 },\n      \"minecraft:emitter_shape_point\": {},\n      \"minecraft:particle_lifetime_expression\": { \"max_lifetime\": \"variable.lifetime ?? 1.1\" },\n      \"minecraft:particle_appearance_billboard\": {\n        \"size\": [0.3, 0.3],\n        \"facing_camera_mode\": \"emitter_transform_xz\",\n        \"uv\": {\n          \"texture_width\": 128,\n          \"texture_height\": 128,\n          \"uv\": [56, 0],\n          \"uv_size\": [8, 8]\n        }\n      },\n      \"minecraft:particle_appearance_tinting\": {\n        \"color\": [\"variable.color.r ?? 1\", \"variable.color.g ?? 0.2\", \"variable.color.b ?? 0.2\", \"variable.color.a ?? 0.8\"]\n      }\n    }\n  }\n}\n"}};
(() => {
// Pure build logic shared by the website and tools/gen-index.mjs: generate
// modules/index.js for a chosen module set, fill in the manifest's pack
// settings (the gear on the Behavior Packs screen), set the version, and zip
// the result. No DOM or Node APIs, so it runs in both.

const identOf = (id) => id.replace(/-(\w)/g, (_, c) => c.toUpperCase());

/** @param {Array<{id: string, name: string, default: boolean}>} included modules in modules.json order */
function generateIndex(included) {
  const meta = Object.fromEntries(included.map((m) => [m.id, { name: m.name, default: m.default }]));
  return `// GENERATED by tools/gen-index.mjs from modules.json. Do not edit by hand.
${included.map((m) => `import ${identOf(m.id)} from "./${m.id}/index.js";`).join("\n")}

export const moduleMeta = ${JSON.stringify(meta, null, 2)};

export default [${included.map((m) => identOf(m.id)).join(", ")}];
`;
}

/** Pack setting name for a module's world switch, or one of its world fields. */
const packSettingName = (id, key) => `qol:${id.replace(/-/g, "_")}${key ? `_${key}` : ""}`;

/**
 * Manifest v3 "settings" for the included modules: a world-wide on/off per
 * module (`qol:tree_felling`) plus any world fields from modules.json
 * (`qol:tree_felling_cap`). One colon, no hyphens, to stay a plain identifier.
 * Read in game by core/world.js via world.getPackSettings().
 * @param {Array<{id: string, name: string, world?: Array<any>}>} included
 */
function generatePackSettings(included) {
  const settings = [
    { type: "label", text: "World-wide switches (world owner only). Each player picks their own settings in game: sneak + jump." },
  ];
  for (const m of included) {
    settings.push({ type: "toggle", text: m.name, name: packSettingName(m.id), default: true });
  }
  const fields = included.flatMap((m) => (m.world ?? []).map((f) => ({ m, f })));
  if (fields.length) settings.push({ type: "label", text: "World limits (players can lower these, never raise them)" });
  for (const { m, f } of fields) {
    const { key, ...rest } = f;
    settings.push({ ...rest, name: packSettingName(m.id, key) });
  }
  return settings;
}

/**
 * @param {{ manifest: string, modules: Array<any>, files: Record<string, string> }} pack
 * @param {string[]} selectedIds
 * @param {[number, number, number]} version
 * @returns {Array<{ path: string, data: string }>} files relative to the pack root
 */
function buildPackFiles(pack, selectedIds, version) {
  const chosen = new Set(selectedIds);
  const included = pack.modules.filter((m) => chosen.has(m.id) && m.hasCode);

  const manifest = JSON.parse(pack.manifest);
  // Manifest v3 wants "1.2.3" strings; v2 wants [1, 2, 3].
  const v = manifest.format_version >= 3 ? version.join(".") : version;
  manifest.header.version = v;
  for (const mod of manifest.modules) mod.version = v;
  if (manifest.format_version >= 3) manifest.settings = generatePackSettings(included);

  const out = [{ path: "manifest.json", data: JSON.stringify(manifest, null, 2) + "\n" }];
  for (const [path, data] of Object.entries(pack.files)) {
    if (path === "scripts/modules/index.js") continue;
    const moduleId = path.match(/^scripts\/modules\/([^/]+)\//)?.[1];
    if (moduleId && !chosen.has(moduleId)) continue;
    out.push({ path, data });
  }
  out.push({ path: "scripts/modules/index.js", data: generateIndex(included) });
  return out;
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(bytes) {
  let c = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

/** Store-only zip (no compression: the pack is tiny). Fixed timestamp so builds are reproducible. */
function makeZip(entries) {
  const enc = new TextEncoder();
  const DOS_DATE = ((2026 - 1980) << 9) | (1 << 5) | 1;
  const parts = [];
  const central = [];
  let offset = 0;

  for (const { path, data } of entries) {
    const name = enc.encode(path);
    const bytes = typeof data === "string" ? enc.encode(data) : data;
    const crc = crc32(bytes);

    const local = new DataView(new ArrayBuffer(30));
    local.setUint32(0, 0x04034b50, true);
    local.setUint16(4, 20, true);
    local.setUint16(6, 0x0800, true); // UTF-8 names
    local.setUint16(8, 0, true); // store
    local.setUint16(10, 0, true);
    local.setUint16(12, DOS_DATE, true);
    local.setUint32(14, crc, true);
    local.setUint32(18, bytes.length, true);
    local.setUint32(22, bytes.length, true);
    local.setUint16(26, name.length, true);
    parts.push(new Uint8Array(local.buffer), name, bytes);

    const cd = new DataView(new ArrayBuffer(46));
    cd.setUint32(0, 0x02014b50, true);
    cd.setUint16(4, 20, true);
    cd.setUint16(6, 20, true);
    cd.setUint16(8, 0x0800, true);
    cd.setUint16(10, 0, true);
    cd.setUint16(12, 0, true);
    cd.setUint16(14, DOS_DATE, true);
    cd.setUint32(16, crc, true);
    cd.setUint32(20, bytes.length, true);
    cd.setUint32(24, bytes.length, true);
    cd.setUint16(28, name.length, true);
    cd.setUint32(42, offset, true);
    central.push(new Uint8Array(cd.buffer), name);

    offset += 30 + name.length + bytes.length;
  }

  const centralSize = central.reduce((n, p) => n + p.length, 0);
  const end = new DataView(new ArrayBuffer(22));
  end.setUint32(0, 0x06054b50, true);
  end.setUint16(8, entries.length, true);
  end.setUint16(10, entries.length, true);
  end.setUint32(12, centralSize, true);
  end.setUint32(16, offset, true);

  const all = [...parts, ...central, new Uint8Array(end.buffer)];
  const zip = new Uint8Array(all.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of all) {
    zip.set(p, at);
    at += p.length;
  }
  return zip;
}

/** True if any chosen module needs the companion resource pack (overlay particles). */
function needsResourcePack(pack, selectedIds) {
  const chosen = new Set(selectedIds);
  return pack.modules.some((m) => chosen.has(m.id) && m.resources);
}

/** `.mcaddon`: a zip holding the behavior pack folder, plus the resource pack folder if needed. */
function buildAddon(pack, selectedIds, version, folder = "QoL_BP") {
  const files = buildPackFiles(pack, selectedIds, version).map((f) => ({ path: `${folder}/${f.path}`, data: f.data }));
  if (pack.resourcePack && needsResourcePack(pack, selectedIds)) {
    for (const [path, data] of Object.entries(pack.resourcePack)) {
      if (path === "manifest.json") {
        const m = JSON.parse(data);
        m.header.version = version;
        for (const mod of m.modules) mod.version = version;
        files.push({ path: "QoL_RP/manifest.json", data: JSON.stringify(m, null, 2) + "\n" });
      } else {
        files.push({ path: `QoL_RP/${path}`, data });
      }
    }
  }
  return makeZip(files);
}



window.QOL_BUILDER = { buildAddon, buildPackFiles, generateIndex, generatePackSettings, makeZip, crc32 };
})();
